  --auth-panel-shadow: var(--color-palette-9537528770ce);
  --surface-card: var(--color-palette-f2074b6cef37);
  --text-primary: var(--color-palette-dd15e6f7d489);
  --text-secondary: var(--color-palette-66341b70b395);
  --text-muted: var(--color-palette-177804c22590);
  --border-default: var(--color-palette-bfd4f8ffcad7);
  --message-bubble-bg: var(--color-palette-f2074b6cef37);
  --message-bubble-border: var(--color-palette-4851b374b731);
