  --accent-primary-hover-light: var(--color-palette-0ad7ddd51778);
  --accent-soft-light: var(--color-palette-93ef761bd491);
  --accent-border-soft-light: var(--color-palette-b9669148c06a);
  --focus-ring-light: var(--color-palette-765c00aef995);
  --focus-shadow-light: var(--color-palette-eba14c9ca936);
  --outline-soft-light: var(--color-palette-06f95ac48318);
  --accent-ring-light: var(--color-palette-428215234d91);
  --accent-primary-dark: var(--color-palette-8940f2c623d0);
  --accent-primary-hover-dark: var(--color-palette-928ee44540c3);
  --accent-soft-dark: var(--color-palette-7e2ac9450b05);
  --accent-border-soft-dark: var(--color-palette-b51de63d0eac);
  --focus-ring-dark: var(--color-palette-43bc9d0f627d);
  --focus-shadow-dark: var(--color-palette-3cbe305ad212);
  --outline-soft-dark: var(--color-palette-904c53fb1685);
  --accent-ring-dark: var(--color-palette-b6e559087702);
  --accent-primary: var(--accent-primary-light);
  --accent-primary-hover: var(--accent-primary-hover-light);
  --accent-soft: var(--accent-soft-light);
  --accent-border-soft: var(--accent-border-soft-light);
  --message-bubble-mine-bg: var(--accent-soft);
  --message-bubble-mine-border: var(--accent-border-soft);
  --focus-ring: var(--focus-ring-light);
  --focus-shadow: var(--focus-shadow-light);
  --outline-soft: var(--outline-soft-light);
  --accent-ring: var(--accent-ring-light);
  --danger: var(--color-palette-c36d4cdccdc9);
  --danger-soft: var(--color-palette-e9ab07065e4e);
