  --float-radius-bubble: 20px;
  --float-radius-pill: 999px;
  --message-gutter-x: 16px;
  --chat-floating-header-overlap: 60px;
  --float-shadow: 0 20px 40px var(--color-palette-6190a6c871e7);
  --float-shadow-soft: 0 8px 24px var(--color-palette-5338a3860b78);
  --nav-active-pill-opacity: 0.2;
  --wallpaper-dot-size: 20px;
  --wallpaper-dot-color: var(--color-palette-dbd729b0a3fb);
  --wallpaper-background-size: var(--wallpaper-dot-size) var(--wallpaper-dot-size), auto;
  --wallpaper-background-repeat: repeat, no-repeat;
  --wallpaper-background-position: 0 0, center;
  --wallpaper-custom-image: none;
  --input-text: var(--color-palette-dd15e6f7d489);
  --input-placeholder: var(--color-palette-177804c22590);
  --bubble-outgoing: var(--accent-primary);
  --bubble-incoming: var(--color-palette-f2074b6cef37);
  --nav-pill-inset-x: 16px;
