  --stovo-primary: var(--accent-primary);
  --canvas-amoled: var(--color-palette-7b2817bf9b80);
  --island-surface: var(--color-palette-95b1a9665923);
  --island-surface-raised: var(--color-palette-47ed8310ca0c);
  --mobile-glass-surface: color-mix(in oklab, var(--surface-card) 90%, transparent);
  --mobile-glass-surface-strong: color-mix(in oklab, var(--surface-card) 94%, transparent);
  --mobile-glass-surface-soft: color-mix(in oklab, var(--surface-card) 84%, transparent);
  --mobile-glass-border: color-mix(in oklab, var(--border-strong) 52%, var(--color-palette-4cea3afb98e3) 48%);
  --mobile-glass-highlight: var(--color-palette-b287e65b6395);
  --mobile-glass-shadow: 0 8px 26px var(--color-palette-9537528770ce);
  --nav-pill-shadow:
    0 12px 28px var(--color-palette-9588d47ed92f),
    0 4px 10px var(--color-palette-094812fca966);
  --mobile-glass-blur: 20px;
  --chat-list-bottom-inset: calc(
    var(--fab-size) + 16px + var(--nav-pill-height) + var(--nav-pill-inset-bottom) + 16px
  );
  --nav-rail-width: 72px;
  --surface-elevated: var(--surface-card);
  --text-tertiary: var(--text-muted);
  --surface-raised: var(--background-tertiary);
  --surface-hover: var(--background-panel-accent);
  --border-strong: var(--color-palette-e2442d83b3a8);
  --card-background: var(--surface-card);
  --accent: var(--accent-primary);
  --message-scale: 1;
  --message-font-family: var(--font-family-ui);
  --avatar-custom-bg: var(--color-palette-1d35b820cb2a);
  color: var(--text-primary);
  background: var(--background-secondary);
  font-family: var(--font-family-ui);
  font-size: var(--font-size-body);
  font-synthesis: none;
  line-height: 1.5;
  text-rendering: optimizeLegibility;
}

.chat-detail .messages-panel {
  animation: chatPanelContentFade 0.12s ease-out;
}

@keyframes chatPanelContentFade {
  from {
    opacity: 0.85;
  }
  to {
    opacity: 1;
  }
}

:root[data-accent="green"] {
  --accent-primary-light: var(--color-palette-6fe2857611b4);
  --accent-primary-hover-light: var(--color-palette-dd0e024de21c);
  --accent-soft-light: var(--color-palette-64033be9a6ab);
  --accent-border-soft-light: var(--color-palette-52cca7c6db66);
  --focus-ring-light: var(--color-palette-0d2916e37d17);
  --focus-shadow-light: var(--color-palette-ddbe9a31eddf);
  --outline-soft-light: var(--color-palette-a79b870e5df5);
  --accent-ring-light: var(--color-palette-d6289f6e2822);
  --accent-primary-dark: var(--color-palette-0f176030df85);
  --accent-primary-hover-dark: var(--color-palette-2c565f8f0651);
  --accent-soft-dark: var(--color-palette-5fcb625f5a93);
  --accent-border-soft-dark: var(--color-palette-0f176030df85);
  --focus-ring-dark: var(--color-palette-e82dbbf7e1ef);
  --focus-shadow-dark: var(--color-palette-7d4ab1673032);
  --outline-soft-dark: var(--color-palette-e6a0706c4b78);
  --accent-ring-dark: var(--color-palette-e82dbbf7e1ef);
}

/* ── Call popup backdrop overlay (desktop, non-minimized) ───────── */
.call-popup-backdrop-overlay {
  position: fixed;
  inset: 0;
  background: var(--color-palette-554de51a1e86);
  z-index: 199;
}

/* ── Call popup (floating window) ─────────────────────────────── */
.call-popup {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 200;
  width: min(720px, calc(100vw - 40px));
  background: var(--surface-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-surface);
  box-shadow: 0 12px 48px var(--color-palette-554de51a1e86);
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 14px 16px 16px;
  overflow: hidden;
  opacity: 1;
  transition:
    opacity var(--motion-surface-duration) var(--motion-route-ease),
    transform var(--motion-surface-duration) var(--motion-route-ease),
    box-shadow var(--motion-surface-duration) var(--motion-route-ease);
}

.call-popup.call-popup-group-call:not(.call-popup-minimized):not(.call-popup-fullscreen) {
  width: min(960px, calc(100vw - 40px));
  height: min(640px, calc(100dvh - 40px));
  max-height: calc(100dvh - 40px);
  box-sizing: border-box;
  padding: 20px 24px 24px;
  gap: 18px;
  background: var(--color-palette-7b2817bf9b80);
  border-color: var(--color-palette-b749cc259197);
}
.call-popup.call-popup-group-call--sharing:not(.call-popup-minimized):not(.call-popup-fullscreen) {
  width: min(1120px, calc(100vw - 40px));
  height: min(760px, calc(100dvh - 40px));
  padding: 22px 26px 26px;
  gap: 20px;
}

.call-popup-group-call .call-popup-ctrl-row {
  flex-wrap: nowrap;
  gap: 10px;
  width: 100%;
}

.call-popup-group-call .call-ctrl-btn {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
}

.call-popup-group-call .call-ctrl-btn--invite {
  width: 40px;
  height: 40px;
}

.call-popup-group-call .call-popup-header-actions > .icon-button {
  flex: 0 0 40px;
  width: 40px;
  height: 40px;
  min-width: 40px;
  min-height: 40px;
  padding: 0;
  border-radius: var(--radius-circle);
  box-sizing: border-box;
}

.call-popup-group-call--sharing:not(.call-popup-minimized):not(.call-popup-fullscreen) .call-popup-video-area {
  flex: 1 1 0;
  min-height: 0;
}

.call-popup-group-call--sharing:not(.call-popup-minimized):not(.call-popup-fullscreen) .call-popup-ctrl-row {
  flex: 0 0 auto;
}

.call-popup-group-call.call-popup-fullscreen.call-popup-group-call--sharing .call-popup-ctrl-row {
  gap: 14px;
}

.mock-screen-share-preview {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-rows: clamp(22px, 4.2vw, 38px) minmax(0, 1fr) clamp(5px, 1vw, 9px);
  overflow: hidden;
  background: var(--color-palette-15f45bc65233);
  color: var(--color-palette-4b9a93f1500e);
  font: 500 clamp(6px, .82vw, 12px)/1.3 Inter, system-ui, sans-serif;
  text-align: left;
}
.mock-screen-share-preview__topbar {
  display: flex;
  align-items: center;
  gap: clamp(5px, 1vw, 12px);
  min-width: 0;
  padding: 0 clamp(7px, 1.3vw, 16px);
  background: var(--color-palette-f2074b6cef37);
  border-bottom: 1px solid var(--color-palette-8cd4345d714a);
  color: var(--color-palette-630629029da9);
}
.mock-screen-share-preview__window-dots {
  width: clamp(14px, 2.2vw, 26px);
  height: clamp(4px, .6vw, 7px);
  flex: 0 0 auto;
  border-radius: var(--radius-pill);
  background: linear-gradient(90deg, var(--color-palette-1a75dc9e3972) 0 30%, var(--color-palette-f8e175950dc1) 30% 65%, var(--color-palette-0f176030df85) 65%);
}
.mock-screen-share-preview__topbar-status {
  margin-left: auto;
  overflow: hidden;
  color: var(--color-palette-6d79e8e67697);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mock-screen-share-preview__content {
  display: grid;
  grid-template-columns: minmax(52px, 17%) minmax(0, 1fr);
  min-height: 0;
}
.mock-screen-share-preview__sidebar {
  display: flex;
  flex-direction: column;
  gap: clamp(4px, .8vw, 10px);
  min-width: 0;
  padding: clamp(5px, 1.2vw, 14px);
  background: var(--color-palette-58de29f72917);
  color: var(--color-palette-4e3fd61175ce);
}
.mock-screen-share-preview__brand-mark {
  display: grid;
  width: clamp(13px, 2.1vw, 24px);
  height: clamp(13px, 2.1vw, 24px);
  place-items: center;
  margin-bottom: clamp(3px, .5vw, 7px);
  border-radius: var(--radius-control);
  background: var(--color-palette-15aad04ebb8c);
  color: var(--color-palette-f2074b6cef37);
  font-weight: var(--font-weight-extrabold);
}
.mock-screen-share-preview__sidebar-item {
  overflow: hidden;
  padding: clamp(2px, .45vw, 5px) clamp(3px, .65vw, 8px);
  border-radius: var(--radius-control);
  color: var(--color-palette-1026c1d4e3e2);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mock-screen-share-preview__sidebar-item.is-active { background: var(--color-palette-76e126eaa971); color: var(--color-palette-f2074b6cef37); }
.mock-screen-share-preview__document {
  display: flex;
  flex-direction: column;
  gap: clamp(4px, .8vw, 10px);
  min-width: 0;
  padding: clamp(8px, 2vw, 24px) clamp(10px, 2.4vw, 30px);
  background: var(--color-palette-b646516228d5);
}
.mock-screen-share-preview__eyebrow { color: var(--color-palette-5fb88fe7da65); font-size: var(--font-size-caption); font-weight: var(--font-weight-bold); letter-spacing: .12em; }
.mock-screen-share-preview__document strong { color: var(--color-palette-b0130f9849d7); font-size: clamp(var(--font-size-caption), 1.7vw, var(--font-size-heading)); font-weight: var(--font-weight-bold); }
.mock-screen-share-preview__document-rule { height: 1px; margin: clamp(1px, .3vw, 4px) 0; background: var(--color-palette-7a3d40084260); }
.mock-screen-share-preview__line { display: block; width: 72%; height: clamp(2px, .4vw, 5px); border-radius: var(--radius-control); background: var(--color-palette-737921b81333); }
.mock-screen-share-preview__line--wide { width: 92%; }
.mock-screen-share-preview__line--short { width: 48%; }
.mock-screen-share-preview__cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: clamp(3px, .8vw, 9px); margin: clamp(2px, .5vw, 7px) 0; }
.mock-screen-share-preview__cards span { display: flex; flex-direction: column; gap: clamp(2px, .4vw, 5px); min-width: 0; padding: clamp(4px, .9vw, 11px); border: 1px solid var(--color-palette-62c29774b1ed); border-radius: var(--radius-control); background: var(--color-palette-f2074b6cef37); color: var(--color-palette-2183d5087643); }
.mock-screen-share-preview__cards b { color: var(--color-palette-15aad04ebb8c); font-size: var(--font-size-caption); }
.mock-screen-share-preview__taskbar { display: flex; justify-content: center; gap: clamp(3px, .6vw, 7px); background: var(--color-palette-18c22cba214d); }
.mock-screen-share-preview__taskbar span { width: clamp(3px, .6vw, 7px); height: clamp(3px, .6vw, 7px); margin-top: 1px; border-radius: var(--radius-circle); background: var(--color-palette-0be59ddfd7b4); }

.call-popup-group-call.call-popup-fullscreen.call-popup-group-call--sharing .shared-call-stage .call-grid--screen-share {
  width: 100% !important;
  max-width: 100% !important;
  height: 100% !important;
  max-height: 100%;
  aspect-ratio: auto;
}

.call-popup-group-call .call-popup-ctrl-row .call-ctrl-wrap > span {
  display: none;
}

.call-popup-group-participants {
  width: 100%;
  height: auto;
  max-height: none;
  grid-template-rows: auto;
  grid-auto-rows: auto;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  align-self: stretch;
}

.call-popup-group-call .call-popup-group-participants.voice-grid--2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-template-rows: auto;
}

.call-popup-group-participant {
  min-height: 0;
  aspect-ratio: 16 / 9;
}

.call-popup-group-participant .voice-participant-meta {
  text-align: center;
}

.call-popup-group-call:not(.call-popup-minimized) .call-popup-header-actions {
  position: static;
  margin: 0;
  grid-column: 1;
  grid-row: 1;
}
.call-popup-group-call:not(.call-popup-minimized) .call-popup-header {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) 40px;
  min-height: 40px;
  padding: 0;
}
.call-popup-group-call .call-popup-status { grid-column: 2; grid-row: 1; }
.call-popup-header-invite { margin-left: 8px; flex-shrink: 0; }
.call-popup-group-call .call-popup-header-invite { grid-column: 3; grid-row: 1; margin: 0; width: 40px; height: 40px; }
/* The same shared stage and disabled Intelligence treatment apply to every call. */
.call-popup-audio-stage:empty { display: none; }
.call-popup-group-call .call-popup-audio-stage .call-popup-group-participants {
  aspect-ratio: auto;
  max-height: none;
  width: 100% !important;
  max-width: 100% !important;
}
.call-popup-group-call .call-popup-ctrl-row .call-ctrl-wrap {
  flex-shrink: 0;
}
.call-popup-group-call .guest-device-control {
  flex-shrink: 0;
}
.meeting-intel-card[aria-disabled="true"] .meeting-intel-card-title {
  color: var(--text-muted);
}
.meeting-intel-card[aria-disabled="true"] .meeting-intel-card-icon {
  color: var(--text-muted);
  background: var(--surface-3);
}

@media (min-width: 681px) {
  .call-popup.call-popup-group-call.call-popup-fullscreen > .call-popup-header {
    display: grid;
    position: static;
    top: auto;
    padding: 0;
    flex-shrink: 0;
  }
  .call-popup.call-popup-group-call.call-popup-fullscreen > .call-popup-video-area {
    display: flex;
    position: relative;
    inset: auto;
    flex: 1;
    min-height: 0;
  }
  .call-popup.call-popup-group-call.call-popup-fullscreen {
    padding: 16px 20px 0;
    gap: 16px;
  }
  .call-popup-group-call.call-popup-fullscreen .call-popup-ctrl-row {
    position: static;
    flex-shrink: 0;
    padding: 12px 0 20px;
  }
}

.call-popup-group-call .call-grid__participant-rail {
  overflow: hidden;
  grid-auto-rows: auto;
}
.call-popup-group-call .call-grid__participant-rail:has(> [data-participant-id]:nth-child(4)) {
  overflow-y: auto;
  grid-auto-rows: minmax(0, 1fr);
}

@media (max-width: 680px) {
  .call-popup.call-popup-group-call:not(.call-popup-minimized):not(.call-popup-fullscreen) {
    width: calc(100vw - 24px);
    padding: 16px;
  }

  .call-popup-group-call .call-popup-ctrl-row {
    flex-wrap: wrap;
    max-width: 520px;
    margin-inline: auto;
  }
}

/* Minimized: slim chip — width collapses to fit content */
.call-popup.call-popup-minimized {
  top: 80px;
  left: auto;
  right: 24px;
  transform: none;
  width: max-content;
  max-width: calc(100vw - 48px);
  min-width: 0;
  border-radius: var(--radius-pill);
  padding: 8px 12px;
  gap: 0;
  flex-direction: row;
  align-items: center;
  z-index: 2500;
  box-shadow: 0 10px 36px var(--color-palette-e16ece2e238b);
}

.call-popup-header {
  display: flex;
  align-items: center;
  gap: 8px;
}

.call-popup-status {
  flex: 1;
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
}

.call-popup-notice {
  font-size: var(--font-size-caption);
  color: var(--text-secondary);
}

.call-popup-header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}

.call-popup-header-actions > .icon-button {
  flex: 0 0 42px;
  width: 42px;
  height: 42px;
}

.call-popup-peer-name {
  font-size: var(--font-size-small);
  color: var(--text-secondary);
  margin: 0;
}

/* ── Video area inside popup ── */
.call-popup-video-area {
  position: relative;
  flex: 1 1 0;
  border-radius: 0;
  overflow: visible;
  background: transparent;
  min-height: 0;
}
.call-popup-video-area.call-popup-video-area-hidden {
  display: none;
}

.call-popup-remote-video {
  display: none;
}
.call-popup-remote-video.visible {
  display: block;
  width: 100%;
  max-height: 280px;
  object-fit: contain;
}

.call-popup-local-video {
  display: none;
}
.call-popup-local-video.visible {
  display: block;
  position: absolute;
  bottom: 8px;
  right: 8px;
  width: 88px;
  height: 66px;
  object-fit: contain;
  border-radius: var(--radius-control);
  border: 2px solid var(--color-palette-eafa2ab918ec);
  background: var(--color-palette-be5cc131d721);
  z-index: 10;
}

.call-popup-local-video.visible.mirrored {
  transform: scaleX(-1);
}

/* ── Minimized chip controls ── */
.call-status-chip-controls {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  flex: 0 0 auto;
}

.call-chip-btn {
  aspect-ratio: 1 / 1;
  box-sizing: border-box;
  min-height: 30px;
  min-width: 30px;
  width: 30px !important;
  height: 30px !important;
  flex: 0 0 30px !important;
}

.call-chip-restore {
  margin-left: 2px;
}

.call-popup-ctrl-row {
  flex-wrap: wrap;
  justify-content: center;
}

/* ── Mobile: fullscreen overlay ────────────────────────────────── */
.call-popup.call-popup-fullscreen {
  position: fixed;
  inset: 0;
  top: 0;
  left: 0;
  transform: none;
  width: 100%;
  height: 100%;
  border-radius: 0;
  border: none;
  padding: 0;
  background: var(--color-palette-7b2817bf9b80);
  gap: 0;
  justify-content: flex-end;
  opacity: 1;
  transform: translate3d(0, 0, 0) scale(1);
  animation: call-surface-enter var(--motion-surface-duration) var(--motion-route-ease);
}

.call-popup.call-popup-fullscreen .call-popup-header {
  position: absolute;
  top: max(env(safe-area-inset-top), 16px);
  left: 0;
  right: 0;
  padding: 0 16px;
  z-index: 15;
}

.call-popup.call-popup-fullscreen .call-popup-status {
  color: var(--color-palette-f2074b6cef37);
  font-size: var(--font-size-body);
  text-shadow: 0 1px 4px var(--color-palette-f71fbab13810);
}

.call-popup.call-popup-fullscreen .call-popup-notice {
  color: var(--color-palette-1248f9ab2f1c);
  text-shadow: 0 1px 4px var(--color-palette-f71fbab13810);
}

.call-popup.call-popup-fullscreen .call-popup-video-area {
  position: absolute;
  inset: 0;
  border-radius: 0;
  min-height: unset;
  z-index: 1;
}

.call-popup.call-popup-fullscreen .call-popup-remote-video.visible {
  display: block;
  width: 100%;
  height: 100%;
  max-height: none;
  object-fit: contain;
}

.call-popup.call-popup-fullscreen .call-popup-local-video.visible {
  display: block;
  position: absolute;
  top: max(env(safe-area-inset-top), 16px);
  right: 12px;
  bottom: auto;
  width: 28vw;
  max-width: 110px;
  height: auto;
  aspect-ratio: 3 / 4;
  border-radius: var(--radius-control);
  border: 2px solid var(--color-palette-c5c7a76d7255);
  background: var(--color-palette-be5cc131d721);
  z-index: 20;
  object-fit: contain;
}

.call-popup.call-popup-fullscreen .call-popup-local-video.visible.mirrored {
  transform: scaleX(-1);
}

.call-popup.call-popup-fullscreen .call-popup-ctrl-row {
  position: relative;
  z-index: 10;
  padding: 20px 24px max(env(safe-area-inset-bottom), 28px);
  background: linear-gradient(transparent, var(--color-palette-b491005d89ad));
  justify-content: center;
  gap: 28px;
  transition:
    opacity var(--motion-surface-duration) var(--motion-route-ease),
    transform var(--motion-surface-duration) var(--motion-route-ease);
}

.call-popup.call-popup-fullscreen .call-ctrl-wrap > span {
  color: var(--color-palette-ec8f9ad7eab9);
}

.call-popup.call-popup-fullscreen .call-ctrl-btn {
  background: var(--color-palette-b92166deed41);
  color: var(--color-palette-f2074b6cef37);
  border-color: transparent;
}
.call-popup.call-popup-fullscreen .call-ctrl-btn--invite {
  border-color: var(--color-palette-2c8dadf03d5e);
}
.call-popup.call-popup-fullscreen .call-ctrl-btn:hover {
  background: var(--color-palette-f6a93a8e2ede);
}
.call-popup.call-popup-fullscreen .call-ctrl-btn.is-muted {
  background: var(--color-palette-d635c939daff);
  color: var(--color-palette-c5c7a76d7255);
}
.call-popup.call-popup-fullscreen .call-ctrl-btn.end-btn {
  background: var(--color-palette-0695333e5710);
  color: var(--color-palette-f2074b6cef37);
  border-color: transparent;
}
.call-popup.call-popup-fullscreen .call-ctrl-btn.accept-btn {
  background: var(--color-palette-bea8539e6999);
  color: var(--color-palette-f2074b6cef37);
  border-color: transparent;
}

/* Minimized on mobile: media host only — visible bar lives in chat chrome */
.call-popup.call-popup-fullscreen.call-popup-minimized.call-popup-slim-host {
  background: transparent;
  border: none;
  box-shadow: none;
  height: 1px;
  inset: auto;
  left: -9999px;
  overflow: hidden;
  padding: 0;
  pointer-events: none;
  position: fixed;
  top: 0;
  width: 1px;
  z-index: -1;
  opacity: 0;
  transform: translate3d(0, 18px, 0) scale(0.98);
}

@keyframes call-surface-enter {
  from {
    opacity: 0;
    transform: translate3d(0, 24px, 0) scale(0.985);
  }

  to {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}

.call-popup.call-popup-fullscreen.call-popup-minimized.call-popup-slim-host .call-popup-header {
  display: none;
}

/* ── Desktop popup avatar (audio call / video off) ─────────────── */
.call-popup-avatar-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 8px 0 4px;
}

.call-popup-avatar-circle {
  position: relative;
  width: 64px;
  height: 64px;
  border-radius: var(--radius-circle);
  background: linear-gradient(140deg, var(--color-palette-c5c97d3b3428), var(--color-palette-3ed7764068c1));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-heading);
  font-weight: var(--font-weight-bold);
  color: var(--color-palette-f2074b6cef37);
  border: 2px solid var(--color-palette-b749cc259197);
  flex-shrink: 0;
}

.call-popup-avatar-ring {
  position: absolute;
  inset: -10px;
  border-radius: var(--radius-circle);
  border: 1.5px solid var(--color-palette-616ae60acd7d);
  animation: call-audio-pulse 1.5s ease-in-out infinite;
}

.call-popup-avatar-ring:nth-child(2) {
  inset: -20px;
  animation-delay: 0.3s;
}

@keyframes call-audio-pulse {
  0%, 100% { opacity: 0.1; transform: scale(0.94); }
  50%       { opacity: 0.85; transform: scale(1.0); }
}

.call-popup-avatar-ring.silent {
  animation: none;
  opacity: 0;
}
.call-popup-avatar-area.is-speaking .call-popup-avatar-circle {
  box-shadow: 0 0 0 3px var(--color-palette-449c31647178), 0 0 20px var(--color-palette-609c0e62a493);
}

.call-popup-waveform {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  height: 18px;
}

.call-popup-wave-bar {
  width: 3px;
  border-radius: var(--radius-small);
  background: var(--color-palette-09ed3334d65d);
  animation: call-wave 1.1s ease-in-out infinite;
}

.call-popup-wave-bar:nth-child(1) { height:  5px; animation-delay: 0.00s; }
.call-popup-wave-bar:nth-child(2) { height: 11px; animation-delay: 0.10s; }
.call-popup-wave-bar:nth-child(3) { height: 16px; animation-delay: 0.20s; }
.call-popup-wave-bar:nth-child(4) { height:  9px; animation-delay: 0.30s; }
.call-popup-wave-bar:nth-child(5) { height: 13px; animation-delay: 0.15s; }

.call-popup-wave-bar.silent {
  animation: none;
  height: 3px !important;
  opacity: 0.2;
  background: var(--color-palette-9fd3860e0ba9);
}

@keyframes call-wave {
  0%, 100% { transform: scaleY(0.3); }
  50%       { transform: scaleY(1); }
}

/* ── Circular call controls (banner + modal) ── */
.call-ctrl-row {
  display: flex;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 18px;
}

.call-ctrl-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}

.call-ctrl-wrap > span {
  color: var(--text-tertiary);
  font-size: var(--font-size-micro);
  letter-spacing: 0.01em;
  white-space: nowrap;
}

.call-ctrl-btn {
  align-items: center;
  background: var(--surface-raised);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-circle);
  color: var(--text-primary);
  cursor: pointer;
  display: flex;
  flex-shrink: 0;
  height: 48px;
  justify-content: center;
  padding: 0;
  transition: background 0.14s, color 0.14s, border-color 0.14s, opacity 0.14s;
  width: 48px;
}

.call-ctrl-btn:hover {
  opacity: 0.82;
}

.call-ctrl-btn.is-active {
  background: var(--accent-primary);
  border-color: var(--accent-primary);
  color: var(--color-palette-f2074b6cef37);
}

.call-ctrl-btn--invite {
  border-color: color-mix(in oklab, var(--accent-primary) 55%, var(--border-default));
  box-shadow: none !important;
}

.call-popup.call-popup-fullscreen .call-ctrl-btn--invite {
  border-color: var(--color-palette-2c8dadf03d5e);
  box-shadow: none !important;
}

.call-ctrl-btn--invite.is-active {
  border-color: var(--accent-border-soft);
  box-shadow: none !important;
}

.call-grid--presenting {
  align-content: stretch;
}

.call-grid--screen-share {
  grid-template-columns: minmax(0, 5fr) minmax(112px, 1fr);
  grid-template-rows: minmax(0, 1fr);
  align-items: stretch;
  gap: 12px;
}

.call-grid--screen-share > .call-grid__tile--screen {
  grid-column: 1;
  grid-row: 1;
  width: 100%;
  height: auto;
  min-height: 0;
  aspect-ratio: var(--screen-aspect-ratio, 16 / 9);
  align-self: stretch;
  justify-self: stretch;
}

.call-grid__participant-rail {
  grid-column: 2;
  grid-row: 1;
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  align-self: stretch;
  align-content: start;
  gap: 8px;
  overflow: hidden;
  container-type: inline-size;
}

.call-grid__participant-pin {
  position: relative;
  width: 100%;
  min-height: 0;
  aspect-ratio: 16 / 9;
}

.call-grid__remote-rail {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-auto-rows: max-content;
  min-width: 0;
  overflow-x: hidden;
  align-content: start;
  gap: 8px;
  min-height: 0;
  overflow-y: auto;
}

@container (min-width: 240px) {
  .call-grid__remote-rail { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

.call-grid__remote-rail > [data-participant-id] {
  position: relative;
  width: 100%;
  height: auto !important;
  min-height: 0;
  aspect-ratio: 16 / 9;
}

.call-grid--screen-share-bottom {
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
}

.call-grid--screen-share-bottom .call-grid__tile--screen {
  grid-column: 1;
  grid-row: 2;
  align-self: center;
  height: auto;
  max-height: 100%;
  max-width: 100%;
  aspect-ratio: 16 / 9;
}

.call-grid--screen-share-bottom .call-grid__participant-rail {
  grid-column: 1;
  grid-row: 1;
  display: flex;
  height: clamp(72px, 11vh, 90px);
  align-items: flex-start;
  gap: 6px;
  overflow-x: auto;
  overflow-y: hidden;
}

.call-grid--screen-share-bottom .call-grid__participant-pin,
.call-grid--screen-share-bottom .call-grid__remote-rail > [data-participant-id] {
  flex: 0 0 auto;
  width: auto;
  height: 100% !important;
  aspect-ratio: 16 / 9;
}

.call-grid--screen-share-bottom .call-grid__remote-rail {
  display: flex;
  flex: 1 1 auto;
  gap: 6px;
  overflow: visible;
  overflow-x: auto;
  overflow-y: hidden;
}

.call-grid__participant-rail .call-grid__tile,
.call-grid__remote-rail .call-grid__tile {
  width: 100%;
  height: 100%;
  min-height: 0;
  aspect-ratio: 16 / 9;
}

.call-grid__participant-rail .call-grid__avatar-circle,
.call-grid__remote-rail .call-grid__avatar-circle {
  width: 40px;
  height: 40px;
}

.shared-call-stage .call-grid--screen-share > .call-grid__tile--screen {
  width: 100%;
  height: auto;
  aspect-ratio: var(--screen-aspect-ratio, 16 / 9);
  align-self: center;
  justify-self: stretch;
  max-height: 100%;
  max-width: 100%;
}
.call-grid__tile--screen .call-grid__video { object-position: center top; }

@media (max-width: 720px) {
  .call-grid--screen-share {
    grid-template-columns: minmax(0, 1fr) !important;
    grid-template-rows: minmax(0, 1fr) auto;
  }

  .shared-call-stage .call-grid--screen-share {
    aspect-ratio: auto;
    height: 100% !important;
    max-height: 100%;
  }

  .call-grid--screen-share > .call-grid__tile--screen {
    grid-column: 1 !important;
    grid-row: 1;
  }

  .call-grid--screen-share .call-grid__participant-rail {
    display: flex;
    align-items: flex-start;
    grid-column: 1;
    grid-row: 2;
    height: clamp(72px, 11vh, 90px);
    overflow: hidden;
  }

  .call-grid--screen-share .call-grid__participant-pin,
  .call-grid--screen-share .call-grid__remote-rail > [data-participant-id] {
    flex: 0 0 auto;
    width: auto;
    height: 100% !important;
    aspect-ratio: 16 / 9;
  }

  .call-grid--screen-share .call-grid__participant-pin .call-grid__avatar-circle,
  .call-grid--screen-share .call-grid__remote-rail .call-grid__avatar-circle {
    width: 36px;
    height: 36px;
  }

  .call-grid--screen-share .call-grid__remote-rail {
    display: flex;
    align-items: center;
    height: 100%;
    min-width: 0;
    overflow-x: auto;
    overflow-y: hidden;
  }

  .call-grid--screen-share-bottom {
    grid-template-rows: auto minmax(0, 1fr);
  }

  .call-grid--screen-share-bottom > .call-grid__tile--screen {
    grid-row: 2;
  }

  .call-grid--screen-share-bottom .call-grid__participant-rail {
    grid-row: 1;
  }
}

.call-grid--presenting:not(.call-grid--screen-share) .call-grid__tile--screen {
  max-height: min(52vh, 420px);
}

.call-grid--presenting .call-grid__tile--screen .call-grid__video {
  object-fit: contain;
}

.call-ctrl-btn.is-muted {
  background: var(--color-palette-4b5450530075);
  border-color: transparent;
  color: var(--color-palette-3871da342003);
}

[data-theme-mode="dark"] .call-ctrl-btn.is-muted {
  background: var(--color-palette-2f89846cd9c9);
  color: var(--color-palette-1a75dc9e3972);
}

.call-ctrl-btn.accept-btn {
  background: var(--color-palette-3c5c1ab6c5fd);
  border-color: var(--color-palette-3c5c1ab6c5fd);
  color: var(--color-palette-f2074b6cef37);
  height: 56px;
  width: 56px;
}

.call-ctrl-btn.accept-btn:hover {
  background: var(--color-palette-7d4ff8ff7b94);
  opacity: 1;
}

.call-ctrl-btn.end-btn {
  background: var(--color-palette-3871da342003);
  border-color: var(--color-palette-3871da342003);
  color: var(--color-palette-f2074b6cef37);
}

.call-ctrl-btn.end-btn:hover {
  background: var(--color-palette-3871da342003);
  border-color: var(--color-palette-3871da342003);
  color: var(--color-palette-f2074b6cef37);
  opacity: 1;
  transform: none;
}

.call-ctrl-btn.end-btn:active {
  background: var(--color-palette-3871da342003);
  border-color: var(--color-palette-3871da342003);
  color: var(--color-palette-f2074b6cef37);
  opacity: 1;
  transform: none;
}

.call-popup.call-popup-fullscreen .call-ctrl-btn.end-btn:hover,
.call-popup.call-popup-fullscreen .call-ctrl-btn.end-btn:active {
  background: var(--color-palette-0695333e5710);
  border-color: transparent;
  color: var(--color-palette-f2074b6cef37);
  opacity: 1;
  transform: none;
}

/* ── AI Transcript control button ── */
.call-ctrl-btn--transcript {
  border-radius: var(--radius-surface);
  border-color: color-mix(in oklab, var(--accent-primary) 40%, var(--border-default));
}

.call-ctrl-btn--transcript.is-recording {
  background: color-mix(in oklab, var(--color-palette-3871da342003) 18%, transparent);
  border-color: var(--color-palette-3871da342003);
  color: var(--color-palette-3871da342003);
  animation: transcript-recording-pulse 1.6s ease-in-out infinite;
}

.call-ctrl-btn--transcript.is-processing {
  background: color-mix(in oklab, var(--color-palette-4542dca0dfae) 14%, transparent);
  border-color: color-mix(in oklab, var(--color-palette-4542dca0dfae) 60%, transparent);
  color: var(--color-palette-4542dca0dfae);
  pointer-events: none;
}

@keyframes transcript-recording-pulse {
  0%, 100% { box-shadow: 0 0 0 0 var(--color-palette-e29177125f23); }
  50%       { box-shadow: 0 0 0 6px var(--color-palette-029db29525ca); }
}

[data-theme-mode="dark"] .call-ctrl-btn--transcript.is-recording {
  background: var(--color-palette-2f89846cd9c9);
  color: var(--color-palette-1a75dc9e3972);
}

/* ── Transcript panel overlay ── */
.transcript-panel {
  position: absolute;
  top: 8px;
  right: 8px;
  bottom: 8px;
  width: min(340px, 90vw);
  background: var(--surface-raised);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-surface);
  box-shadow: 0 8px 32px var(--color-palette-d7c16d3d16dd);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  z-index: 50;
  animation: transcript-panel-in 0.2s ease-out;
}

@keyframes transcript-panel-in {
  from { opacity: 0; transform: translateX(16px); }
  to   { opacity: 1; transform: translateX(0); }
}

.transcript-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px 10px 14px;
  border-bottom: 1px solid var(--border-default);
  gap: 8px;
  flex-shrink: 0;
}

.transcript-panel__title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
  color: var(--text-primary);
}

.transcript-panel__header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}

.transcript-panel__icon-btn {
  background: none;
  border: 1px solid transparent;
  border-radius: var(--radius-control);
  color: var(--text-secondary);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  transition: background 0.12s, color 0.12s;
}

.transcript-panel__icon-btn:hover {
  background: var(--surface-subtle);
  color: var(--text-primary);
}

.transcript-panel__body {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.transcript-panel__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  color: var(--text-secondary);
  font-size: var(--font-size-small);
  text-align: center;
  padding: 24px;
}

.transcript-panel__spinner {
  width: 24px;
  height: 24px;
  border: 3px solid var(--border-default);
  border-top-color: var(--accent-primary);
  border-radius: var(--radius-circle);
  animation: spin 0.8s linear infinite;
}

.transcript-panel__section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.transcript-panel__section-title {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-bold);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  margin: 0;
}

.transcript-panel__summary-text {
  font-size: var(--font-size-small);
  line-height: 1.55;
  color: var(--text-primary);
  margin: 0;
  padding: 10px 12px;
  background: var(--surface-subtle);
  border-radius: var(--radius-control);
}

.transcript-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.transcript-panel__list-item {
  font-size: var(--font-size-small);
  line-height: 1.5;
  color: var(--text-primary);
  padding: 7px 10px;
  background: var(--surface-subtle);
  border-radius: var(--radius-control);
  border-left: 3px solid var(--accent-primary);
}

.transcript-panel__segments {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.transcript-panel__segment {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.transcript-panel__segment-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.transcript-panel__speaker {
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  color: var(--accent-primary);
}

.transcript-panel__timestamp {
  font-size: var(--font-size-caption);
  color: var(--text-tertiary, var(--text-secondary));
  font-variant-numeric: tabular-nums;
}

.transcript-panel__segment-text {
  font-size: var(--font-size-small);
  line-height: 1.5;
  color: var(--text-primary);
  margin: 0;
}


/* ── Call settings icon button ── */
.call-settings-icon-btn {
  background: var(--surface-raised, var(--color-palette-3b313dfb66a5));
  border: 1px solid var(--border-default);
  border-radius: var(--radius-control);
  color: var(--text-secondary);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px 8px;
}
.call-settings-icon-btn:hover:not(:disabled) {
  background: var(--surface-hover);
}
.call-settings-icon-btn.active {
  background: var(--accent-soft);
  border-color: var(--accent-border-soft);
  color: var(--accent-primary);
}

/* ── Call settings context menu ── */
.call-settings-context-menu {
  position: fixed;
  z-index: 2600;
  background: var(--surface-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-control);
  box-shadow: 0 8px 24px var(--color-palette-0bcd1015425a);
  padding: 4px;
  min-width: 160px;
}
.call-settings-context-item {
  align-items: center;
  background: transparent;
  border: none;
  border-radius: var(--radius-control);
  color: var(--text-primary);
  cursor: pointer;
  display: flex;
  font-size: var(--font-size-small);
  gap: 8px;
  padding: 4px 8px;
  width: 100%;
  text-align: left;
}
.call-settings-context-item:hover {
  background: var(--surface-hover);
}

/* ── Audio settings popup ── */
.call-audio-popup-backdrop {
  align-items: center;
  background: var(--color-palette-554de51a1e86);
  bottom: 0;
  display: flex;
  justify-content: center;
  left: 0;
  position: fixed;
  right: 0;
  top: 0;
  z-index: 2600;
}

.call-audio-popup {
  background: var(--surface-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-surface);
  box-shadow: 0 20px 48px var(--color-palette-279245c0d6e0);
  max-height: calc(100vh - 80px);
  overflow-y: auto;
  width: 340px;
  scrollbar-width: thin;
  scrollbar-color: var(--border-default) transparent;
}
.call-audio-popup::-webkit-scrollbar { width: 4px; }
.call-audio-popup::-webkit-scrollbar-thumb { background: var(--border-default); border-radius: var(--radius-pill); }
.call-audio-popup-header {
  align-items: center;
  border-bottom: 1px solid var(--border-default);
  display: flex;
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
  justify-content: space-between;
  padding: 11px 14px;
}
.call-audio-popup-close {
  align-items: center;
  background: color-mix(in oklab, var(--surface-raised, var(--color-palette-dace4750bb21)) 78%, transparent);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-pill);
  color: var(--text-tertiary);
  cursor: pointer;
  display: flex;
  flex: 0 0 36px;
  height: 36px;
  justify-content: center;
  padding: 0;
  width: 36px;
}
.call-audio-popup-close:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}
.call-audio-popup-body {
  display: flex;
  flex-direction: column;
  padding: 10px 0;
}
.call-audio-popup-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 8px 14px;
}
.call-audio-popup-section + .call-audio-popup-section {
  border-top: 1px solid var(--border-default);
  margin-top: 4px;
  padding-top: 12px;
}
.call-audio-section-label {
  color: var(--text-tertiary);
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.call-audio-popup-warning {
  color: var(--danger-text, var(--color-palette-59dbd125956e));
  font-size: var(--font-size-small);
  padding: 6px 14px 0;
}
.call-audio-popup-note {
  color: var(--text-tertiary);
  font-size: var(--font-size-caption);
}

/* Device selects */
.call-audio-device-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: var(--font-size-small);
  color: var(--text-secondary);
}
.call-audio-device-trigger {
  align-items: center;
  background: var(--background-primary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-control);
  color: var(--text-primary);
  cursor: pointer;
  display: flex;
  font: inherit;
  justify-content: space-between;
  min-height: 42px;
  padding: 7px 10px;
  text-align: left;
  width: 100%;
  gap: 8px;
  min-width: 0;
}
.call-audio-device-trigger > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.call-audio-device-trigger > svg { flex-shrink: 0; }
.call-audio-device-trigger:disabled { cursor: not-allowed; opacity: .55; }
.call-audio-device-select { position: relative; width: 100%; }
.call-audio-device-menu {
  bottom: auto;
  left: auto;
  min-width: 0;
  transform: none;
  z-index: 4000;
  box-sizing: border-box;
}
.call-audio-device-menu::before { display: none; }
.call-audio-device-menu .guest-device-menu-heading { padding: .35rem .5rem; }
.call-audio-device-menu .guest-device-menu-option { min-height: 38px; }
.call-audio-device-select .guest-device-menu-trigger:focus-visible,
.call-audio-device-trigger:focus-visible { outline: 2px solid var(--accent-primary); outline-offset: 2px; }
/* Sliders */
.call-audio-slider-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.call-audio-slider-head {
  align-items: center;
  display: flex;
  font-size: var(--font-size-small);
  color: var(--text-secondary);
  justify-content: space-between;
}
.call-audio-slider-value {
  color: var(--accent-primary);
  font-size: var(--font-size-caption);
  font-variant-numeric: tabular-nums;
  font-weight: var(--font-weight-semibold);
}
.call-audio-slider-row input[type="range"] {
  accent-color: var(--accent-primary);
  cursor: pointer;
  width: 100%;
}
.call-audio-mic-test { color: var(--text-secondary); display: grid; font-size: var(--font-size-caption); gap: 6px; }
.call-audio-mic-test small { color: var(--text-tertiary); font-size: inherit; }
.call-audio-test-sound { align-items: center; background: transparent; border: 1px solid var(--border-default); border-radius: var(--radius-pill); color: var(--text-primary); cursor: pointer; display: flex; font: inherit; font-size: var(--font-size-caption); gap: 6px; justify-content: center; min-height: 34px; }
.call-audio-test-sound:disabled { cursor: not-allowed; opacity: .5; }
.call-audio-sub-sliders {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 4px 0 0;
  margin-top: 2px;
}

/* Toggle group */
.call-audio-toggle-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.call-audio-toggle-row {
  align-items: center;
  background: transparent;
  border: 0;
  display: flex;
  gap: 10px;
  justify-content: space-between;
  padding: 4px 0;
}
.call-audio-toggle-row.disabled {
  opacity: 0.45;
}
.call-audio-toggle-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}
.call-audio-toggle-name {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-medium);
  gap: 5px;
}
.call-audio-toggle-desc {
  color: var(--text-tertiary);
  font-size: var(--font-size-caption);
}

/* iOS-style toggle switch */
.call-audio-toggle-switch {
  cursor: pointer;
  display: inline-block;
  flex-shrink: 0;
  height: 20px;
  position: relative;
  width: 34px;
}
.call-audio-toggle-switch input {
  height: 0;
  opacity: 0;
  width: 0;
}
.call-audio-toggle-slider {
  background: var(--border-default);
  border-radius: var(--radius-bubble);
  bottom: 0;
  cursor: pointer;
  left: 0;
  position: absolute;
  right: 0;
  top: 0;
  transition: background 0.18s;
}
.call-audio-toggle-slider::after {
  background: var(--color-palette-f2074b6cef37);
  border-radius: var(--radius-circle);
  bottom: 2px;
  content: "";
  height: 16px;
  left: 2px;
  position: absolute;
  transition: transform 0.18s;
  width: 16px;
}
.call-audio-toggle-switch input:checked + .call-audio-toggle-slider {
  background: var(--accent-primary);
}
.call-audio-toggle-switch input:checked + .call-audio-toggle-slider::after {
  transform: translateX(14px);
}

/* Speaker mode row */
.call-audio-speaker-row {
  display: flex;
  gap: 6px;
}
.call-audio-speaker-btn {
  align-items: center;
  background: var(--surface-raised);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-control);
  color: var(--text-secondary);
  cursor: pointer;
  display: inline-flex;
  font-size: var(--font-size-small);
  gap: 6px;
  padding: 6px 12px;
}
.call-audio-speaker-btn:hover:not(:disabled) {
  background: var(--surface-hover);
}
.call-audio-speaker-btn.active {
  border-color: var(--accent-primary);
  box-shadow: inset 0 0 0 1px var(--accent-primary);
  color: var(--accent-primary);
}


