* {
  box-sizing: border-box;
}

html {
  background-color: var(--color-palette-7b2817bf9b80);
  overflow-x: hidden;
}

html,
body,
#root {
  min-height: 100%;
}

body {
  background: var(--background-secondary, var(--color-palette-7b2817bf9b80));
  color: var(--text-primary);
  font-family: var(--font-family-ui);
  font-size: var(--font-size-body);
  line-height: var(--line-height-body);
  margin: 0;
  min-width: 320px;
  overflow-x: hidden;
  transition:
    background 160ms ease,
    color 160ms ease;
}

.ms-icon {
  align-items: center;
  display: inline-flex;
  font-family: "Material Symbols Outlined";
  font-size: var(--font-size-heading);
  font-variation-settings: "FILL" 0, "wght" 400, "GRAD" 0, "opsz" 24;
  justify-content: center;
  line-height: 1;
  user-select: none;
}

.ms-icon--filled {
  font-variation-settings: "FILL" 1, "wght" 400, "GRAD" 0, "opsz" 24;
}

.ms-icon--20 {
  font-size: var(--font-size-heading-small);
  font-variation-settings: "FILL" 0, "wght" 400, "GRAD" 0, "opsz" 20;
}

.ms-icon--20.ms-icon--filled {
  font-variation-settings: "FILL" 1, "wght" 400, "GRAD" 0, "opsz" 20;
}

.ms-icon--22 {
  font-size: var(--font-size-heading);
  font-variation-settings: "FILL" 0, "wght" 400, "GRAD" 0, "opsz" 22;
}

.ms-icon--22.ms-icon--filled {
  font-variation-settings: "FILL" 1, "wght" 400, "GRAD" 0, "opsz" 22;
}

.ms-icon--24 {
  font-size: var(--font-size-heading);
  font-variation-settings: "FILL" 0, "wght" 400, "GRAD" 0, "opsz" 24;
}

.ms-icon--24.ms-icon--filled {
  font-variation-settings: "FILL" 1, "wght" 400, "GRAD" 0, "opsz" 24;
}

button,
input,
select {
  font: inherit;
}

button {
  align-items: center;
  background: var(--surface-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-control);
  box-sizing: border-box;
  color: var(--text-primary);
  cursor: pointer;
  display: inline-flex;
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-bold);
  gap: 8px;
  justify-content: center;
  min-height: 36px;
  padding: 0 14px;
  /* Capacitor's Android WebView otherwise paints its own rectangular tap flash. */
  -webkit-tap-highlight-color: transparent;
  transition:
    background 140ms ease,
    border-color 140ms ease,
    color 140ms ease,
    transform 140ms ease;
}

