/* Bottom-bar screens move like a linear carousel. The direction
   comes from the fixed tab order, so jumping between the first and last tab
   never wraps around. We animate the page content while keeping the fixed
   bottom navigation bar untransformed. */
.app-route-layer--forward .app-shell > :not(.app-nav),
.app-route-layer--back .app-shell > :not(.app-nav) {
  animation-duration: var(--motion-page, 300ms);
  animation-fill-mode: backwards;
  animation-timing-function: var(--motion-ease-enter, cubic-bezier(0.22, 1, 0.36, 1));
  will-change: opacity, transform;
}

.app-route-layer--forward .app-shell > :not(.app-nav) {
  animation-name: app-tab-carousel-forward;
}

.app-route-layer--back .app-shell > :not(.app-nav) {
  animation-name: app-tab-carousel-back;
}

@keyframes app-tab-carousel-forward {
  from {
    opacity: 0.35;
    transform: translate3d(32px, 0, 0);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

@keyframes app-tab-carousel-back {
  from {
    opacity: 0.35;
    transform: translate3d(-32px, 0, 0);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .app-route-layer--forward .app-shell > :not(.app-nav),
  .app-route-layer--back .app-shell > :not(.app-nav) {
    animation: none;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

