  gap: 8px;
  grid-template-columns: auto minmax(0, 1fr);
  min-height: 44px;
  padding: 0 12px;
}

.search-field:focus-within {
  border-color: var(--accent-border-soft);
  box-shadow: 0 0 0 3px var(--outline-soft);
}

.search-field input:not([type="checkbox"]):not([type="radio"]) {
