/* Shared app scrollbars match the understated chat treatment. Individual
   components can still opt out with their more-specific hidden/custom rules. */
:where(*) {
  scrollbar-color: var(--border-default) transparent;
  scrollbar-width: thin;
}

:where(*)::-webkit-scrollbar {
  height: 6px;
  width: 6px;
}

:where(*)::-webkit-scrollbar-track {
  background: transparent;
}

:where(*)::-webkit-scrollbar-thumb {
  background: var(--border-default);
  border-radius: var(--radius-pill);
}

/* Mobile application hides scrollbars across all scrollable containers while preserving scrolling functionality */
:root[data-platform="native"],
:root[data-platform="native"] body,
:root[data-platform="native"] * {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

:root[data-platform="native"]::-webkit-scrollbar,
:root[data-platform="native"] body::-webkit-scrollbar,
:root[data-platform="native"] *::-webkit-scrollbar,
:root[data-platform="native"] *::-webkit-scrollbar-track,
:root[data-platform="native"] *::-webkit-scrollbar-thumb {
  display: none !important;
  height: 0 !important;
  width: 0 !important;
}

@media (hover: none) and (pointer: coarse) {
  html,
  body,
  * {
    scrollbar-width: none;
    -ms-overflow-style: none;
  }

  html::-webkit-scrollbar,
  body::-webkit-scrollbar,
  *::-webkit-scrollbar,
  *::-webkit-scrollbar-track,
  *::-webkit-scrollbar-thumb {
    display: none;
    height: 0;
    width: 0;
  }
}

