  font-size: var(--font-size-body);
}

.message-reference {
  border-left: 3px solid var(--accent-primary);
  color: var(--text-secondary);
  display: block;
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-bold);
  line-height: 1.35;
  max-width: 100%;
  overflow: hidden;
  padding-left: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.message-reference-button {
  background: transparent;
  border-top: 0;
  border-right: 0;
  border-bottom: 0;
  cursor: pointer;
  text-align: left;
}

.message-bubble-inner {
  align-items: flex-end;
  display: flex;
  flex-wrap: wrap;
  gap: 0 8px;
}

.message-body {
  flex: 0 1 auto;
  margin: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  position: relative;
  white-space: pre-wrap;
}

.message-bubble p,
.message-body {
  margin: 0;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.message-enlarge-button {
  align-items: center;
  background: transparent;
  border: 0;
  border-radius: var(--radius-circle);
  color: var(--text-secondary);
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 auto;
  height: 28px;
  justify-content: center;
  margin: 0;
  opacity: 0.72;
  padding: 0;
  width: 28px;
}

.message-enlarge-button:hover,
.message-enlarge-button:focus-visible {
  background: color-mix(in oklab, var(--border-default) 45%, transparent);
  color: var(--text-primary);
  opacity: 1;
  outline: none;
}

/* Fullscreen Enlarge / Compose Modal */
.message-enlarge-backdrop {
  align-items: center;
  background: var(--color-palette-b491005d89ad);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  display: flex;
  inset: 0;
  justify-content: center;
  position: fixed;
  z-index: 300;
  padding: 0;
}

.message-enlarge-modal {
  background: var(--surface-bg, var(--color-palette-d6a5747a4c58));
  border: none;
  color: var(--text-primary);
