  flex-direction: column;
  height: 100vh;
  height: 100dvh;
  width: 100vw;
  max-height: 100%;
  max-width: 100%;
  overflow: hidden;
  position: fixed;
  inset: 0;
  z-index: 140;
  animation: composeModalSlideUp 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

@media (min-width: 768px) {
  .message-enlarge-backdrop {
    padding: 24px;
  }

  .message-enlarge-modal {
    position: relative;
    inset: auto;
    width: min(840px, 92vw);
    height: min(680px, 85vh);
    border-radius: var(--radius-panel);
    border: 1px solid var(--border-default, var(--color-palette-5089217ef21a));
    box-shadow: 0 24px 64px var(--color-palette-1ba7a3e2489d);
