.toolbar-btn:hover {
  background: var(--color-palette-c34f5a2a4d80);
  color: var(--text-primary, var(--color-palette-f2074b6cef37));
}

.toolbar-btn.is-active {
  background: var(--accent-primary-light, var(--color-palette-428215234d91));
  color: var(--accent-primary, var(--color-palette-b51de63d0eac));
