/* Telegram-style Inline Image Insertion Popover */
.inline-image-popover {
  position: absolute;
  top: 100%;
  right: 16px;
  width: min(380px, calc(100vw - 32px));
  background: var(--surface-card, var(--color-palette-98c8bbe556ea));
  border: 1px solid var(--border-default, var(--color-palette-5089217ef21a));
  border-radius: var(--radius-surface);
  box-shadow: 0 12px 32px var(--color-palette-4c85ca9b7179);
  padding: 16px;
  z-index: 50;
  margin-top: 6px;
  animation: popoverFade 0.15s ease-out;
}

@keyframes popoverFade {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.inline-image-popover-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.inline-image-popover-header strong {
  font-size: var(--font-size-body);
  color: var(--text-primary);
}

.popover-close-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 4px;
  display: inline-flex;
}

.inline-image-popover-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.inline-image-pick-file-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px;
  border-radius: var(--radius-control);
  background: var(--color-palette-55db6ccfe2fd);
  border: 1px dashed var(--accent-primary, var(--color-palette-b51de63d0eac));
  color: var(--accent-primary, var(--color-palette-b51de63d0eac));
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: background 0.15s ease;
}

.inline-image-pick-file-btn:hover {
  background: var(--color-palette-cfe5d02c1663);
}

.popover-or-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-caption);
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin: 4px 0;
}

.inline-image-url-input {
  width: 100%;
  padding: 9px 12px;
  border-radius: var(--radius-control);
  background: var(--color-palette-5338a3860b78);
  border: 1px solid var(--border-default, var(--color-palette-b749cc259197));
  color: var(--text-primary);
  font-size: var(--font-size-small);
  outline: none;
}

.inline-image-url-input:focus {
  border-color: var(--accent-primary, var(--color-palette-b51de63d0eac));
}

.inline-image-popover-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 4px;
}

.popover-cancel-btn {
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  background: transparent;
  border: 1px solid var(--border-default);
  color: var(--text-primary);
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-medium);
  cursor: pointer;
  transition: all 0.15s ease;
}

.popover-cancel-btn:hover {
  background: var(--surface-hover, var(--color-palette-c34f5a2a4d80));
}

.popover-submit-btn {
  padding: 6px 16px;
  border-radius: var(--radius-pill);
  background: var(--accent-primary, var(--color-palette-b51de63d0eac));
  border: none;
  color: var(--color-palette-f2074b6cef37);
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: all 0.15s ease;
}

.popover-submit-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Emoji picker popover inside compose modal */
.compose-modal-emoji-picker {
  position: absolute;
  bottom: 64px;
  left: 20px;
  z-index: 60;
  box-shadow: 0 12px 32px var(--color-palette-f71fbab13810);
  border-radius: var(--radius-surface);
  overflow: hidden;
