.message-media-album[data-count="2"] {
  aspect-ratio: 2 / 1;
  grid-template-columns: 1fr 1fr;
}

.message-media-album[data-count="3"] {
  aspect-ratio: 4 / 3;
  grid-template-columns: 1.15fr 1fr;
  grid-template-rows: 1fr 1fr;
}

.message-media-album[data-count="3"] > .message-media-album-cell:first-child {
  grid-row: 1 / -1;
}

.message-media-album[data-count="4"] {
  aspect-ratio: 1;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
}

.message-media-album[data-count="5"] {
  aspect-ratio: 1;
  grid-template-areas:
    "a b b"
    "c d e";
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: 1.15fr 1fr;
}

.message-media-album[data-count="5"] > .message-media-album-cell:nth-child(1) { grid-area: a; }
.message-media-album[data-count="5"] > .message-media-album-cell:nth-child(2) { grid-area: b; }
.message-media-album[data-count="5"] > .message-media-album-cell:nth-child(3) { grid-area: c; }
.message-media-album[data-count="5"] > .message-media-album-cell:nth-child(4) { grid-area: d; }
.message-media-album[data-count="5"] > .message-media-album-cell:nth-child(5) { grid-area: e; }

.message-media-album[data-count="6"] {
  aspect-ratio: 1;
  grid-auto-flow: dense;
  grid-auto-rows: 1fr;
  grid-template-columns: 1fr 1fr 1fr;
