.message-bubble:not(.mine).has-photo-attachments .video-player,
.message-bubble:not(.mine):has(.message-video-attachment) .video-player {
  border-radius: var(--radius-surface);
}

.message-bubble:not(.mine).grouped.has-photo-attachments .video-player,
.message-bubble:not(.mine).grouped:has(.message-video-attachment) .video-player {
