.video-player-seek::-webkit-slider-runnable-track,
.video-player-controls input[type="range"]::-webkit-slider-runnable-track {
  background: var(--color-palette-17c27e9f2079);
  border-radius: var(--radius-pill);
  height: 5px;
}

.video-player-seek::-webkit-slider-thumb,
.video-player-controls input[type="range"]::-webkit-slider-thumb {
  appearance: none;
  background: var(--accent-primary);
  border: 2px solid var(--color-palette-f2074b6cef37);
  border-radius: var(--radius-circle);
  height: 20px;
  margin-top: -7.5px;
  width: 20px;
}

.video-player-seek::-moz-range-track,
.video-player-controls input[type="range"]::-moz-range-track {
  background: var(--color-palette-17c27e9f2079);
  border-radius: var(--radius-pill);
  height: 5px;
}

.video-player-seek::-moz-range-thumb,
.video-player-controls input[type="range"]::-moz-range-thumb {
  background: var(--accent-primary);
  border: 2px solid var(--color-palette-f2074b6cef37);
  border-radius: var(--radius-circle);
  height: 18px;
  width: 18px;
}

.video-player-seek:disabled,
.video-player-controls input[type="range"]:disabled {
  cursor: not-allowed;
  opacity: 0.46;
}

.video-player-time,
.video-player-controls output {
  color: var(--color-palette-c801d51c67db);
  font-size: var(--font-size-caption);
  font-variant-numeric: tabular-nums;
  min-width: max-content;
  text-shadow: 0 1px 2px var(--color-palette-2101efd095aa);
}

.video-player-status,
.video-player-error {
  align-items: center;
  background: var(--color-palette-2b5d0be87676);
  border-radius: var(--radius-surface);
  color: var(--color-palette-f2074b6cef37);
  display: inline-flex;
  font-size: var(--font-size-small);
  gap: 8px;
  left: 50%;
  max-width: calc(100% - 32px);
  padding: 8px 12px;
  pointer-events: none;
  position: absolute;
  text-align: center;
  top: 42%;
  transform: translate(-50%, -50%);
  z-index: 2;
}

.video-player-status::before {
  animation: video-player-spin 900ms linear infinite;
  border: 2px solid var(--color-palette-c0ed37419009);
  border-radius: var(--radius-circle);
  border-top-color: var(--accent-primary);
  content: "";
  flex: 0 0 auto;
  height: 16px;
  width: 16px;
}

.video-player-error {
  background: color-mix(in oklab, var(--color-palette-fce188f6bf68) 86%, transparent);
  line-height: 1.35;
}

.video-player-error::before {
  content: none;
}

.video-player:fullscreen {
  aspect-ratio: auto;
  border: 0;
  border-radius: var(--radius-surface);
  height: 100vh;
  max-height: none;
  max-width: none;
  width: 100vw;
}

.video-player:fullscreen .video-player-controls {
  padding-bottom: max(12px, env(safe-area-inset-bottom));
  padding-left: max(12px, env(safe-area-inset-left));
  padding-right: max(12px, env(safe-area-inset-right));
}

.video-player-viewer-backdrop {
  background: var(--color-palette-86a5b58625fb);
  inset: 0;
  position: fixed;
  z-index: 2147483646;
}

.video-player.is-expanded {
  border-radius: var(--radius-surface);
  box-shadow: 0 24px 80px var(--color-palette-e16ece2e238b);
  left: 50%;
  max-height: calc(100dvh - 48px);
  max-width: calc(100vw - 48px);
  min-height: 0;
  position: fixed;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 2147483647;
}

.video-player.is-expanded .video-player-controls {
  padding-bottom: max(12px, env(safe-area-inset-bottom));
  padding-left: max(12px, env(safe-area-inset-left));
  padding-right: max(12px, env(safe-area-inset-right));
}

.messenger-shell--video-pip .video-player.is-session-active:not(.is-expanded) {
  aspect-ratio: auto;
  background: var(--color-palette-7b2817bf9b80);
  border: 0;
  border-radius: 0;
  box-shadow: none;
  height: 100vh;
  inset: 0;
  max-height: none;
  max-width: none;
  min-height: 0;
  position: fixed;
  width: 100vw;
  z-index: 2147483647;
}

.messenger-shell--video-pip .video-player.is-session-active:not(.is-expanded) .video-player-controls,
.messenger-shell--video-pip .video-player.is-session-active:not(.is-expanded) .video-player-status,
.messenger-shell--video-pip .video-player.is-session-active:not(.is-expanded) .video-player-error {
  display: none;
}

@keyframes video-player-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .video-player-control,
  .video-player-controls button {
    transition: none;
  }

  .video-player-status::before {
    animation: none;
  }
}

@media (min-width: 961px) {
  .message-bubble {
    max-width: min(640px, 84%);
  }

  .message-bubble.has-photo-attachments {
    max-width: min(560px, 84%);
  }

  .message-bubble.has-photo-attachments:has(.message-video-attachment),
  .message-bubble:has(.message-video-attachment):not(:has(.message-photo-attachment)) {
    max-width: min(420px, 84%);
    width: min(420px, 84%);
  }

  .message-bubble.has-photo-attachments:has(.message-video-attachment):not(:has(.message-media-album)):has(.video-player.is-portrait),
  .message-bubble:has(.message-video-attachment):not(:has(.message-photo-attachment)):not(:has(.message-media-album)):has(.video-player.is-portrait) {
    max-width: min(300px, 68%);
    width: min(300px, 68%);
  }

  .message-photo-attachment img {
    max-height: 520px;
  }
}

.composer-attachments-strip {
  flex-shrink: 0;
  margin: 0 var(--message-gutter-x) 8px;
  max-width: 100%;
}

.messenger-shell.has-active-chat .composer-attachments-strip {
  margin: 0 var(--message-gutter-x) 8px;
}

.composer-attachments-strip .pending-attachments {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(132px, 100%), 1fr));
  gap: 8px;
  max-height: 224px;
  overflow-y: auto;
  padding: 4px 4px 8px;
}

.pending-attachments {
  gap: 8px;
  padding: 2px 2px 4px;
}

@keyframes pendingAttachmentEnter {
  from {
    opacity: 0;
    transform: scale(0.9) translateY(6px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.pending-attachment-card {
  align-items: center;
  background: var(--island-surface-raised);
  border: none;
  border-radius: var(--radius-surface);
  box-shadow: var(--float-shadow-soft);
  display: grid;
  gap: 8px;
  grid-template-columns: minmax(0, 1fr) auto;
  max-width: min(280px, 100%);
  min-width: 0;
  padding: 8px 8px 8px 10px;
  position: relative;
  animation: pendingAttachmentEnter var(--motion-fast, 180ms) var(--motion-ease-enter, cubic-bezier(0.22, 1, 0.36, 1)) both;
  transition: opacity 160ms var(--motion-ease-exit), transform 160ms var(--motion-ease-exit);
}

.pending-attachment-card--thumb {
  display: block;
  position: relative;
  width: 100%;
  min-width: 0;
  border-radius: var(--radius-surface);
  padding: 0;
  max-width: none;
  grid-template-columns: none;
  box-shadow: none;
  background: transparent;
}

.pending-attachment-card--file {
  flex: 0 0 auto;
  max-width: min(220px, 70vw);
}

.pending-attachment-thumb {
  align-items: center;
  background: var(--background-tertiary);
  border-radius: var(--radius-surface);
  display: inline-flex;
  flex: 0 0 auto;
  height: 64px;
  justify-content: center;
  overflow: hidden;
  width: 64px;
}

.pending-attachment-card--thumb .pending-attachment-thumb {
  border-radius: var(--radius-surface);
  aspect-ratio: 1;
  height: auto;
  width: 100%;
}

.pending-attachment-card--thumb.is-video .pending-attachment-thumb {
  aspect-ratio: 16 / 10;
}

.pending-attachment-thumb img,
.pending-attachment-thumb video {
  display: block;
  height: 100%;
  width: 100%;
}

.pending-attachment-thumb img {
  object-fit: cover;
}

.pending-attachment-card--thumb .pending-attachment-thumb video {
  object-fit: contain;
}

.pending-attachment-thumb-placeholder {
  align-items: center;
  color: var(--text-secondary);
  display: inline-flex;
  height: 100%;
  justify-content: center;
  width: 100%;
}

.pending-attachment-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.pending-attachment-copy strong,
.pending-attachment-copy span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pending-attachment-copy strong {
  color: var(--text-primary);
  font-size: var(--font-size-body);
  font-weight: var(--font-weight-semibold);
}

.pending-attachment-copy span {
  color: var(--text-secondary);
  font-size: var(--font-size-caption);
}

.pending-attachment-card.is-editable {
  cursor: pointer;
  transition: transform 0.15s ease, opacity 0.15s ease;
}

.pending-attachment-card.is-editable:hover {
  opacity: 0.92;
  transform: translateY(-1px);
}

.pending-attachment-remove {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 22px;
  height: 22px;
  min-width: 22px;
  min-height: 22px;
  max-width: 22px;
  max-height: 22px;
  aspect-ratio: 1 / 1;
  border-radius: var(--radius-circle);
  background: var(--color-palette-5c388d52bbd3);
  border: 1px solid var(--color-palette-aacf6e2b68c8);
  color: var(--color-palette-f2074b6cef37);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  margin: 0;
  cursor: pointer;
  z-index: 30;
  box-shadow: 0 2px 6px var(--color-palette-4c85ca9b7179);
  box-sizing: border-box;
  line-height: 1;
  flex-shrink: 0;
  transition: all 0.15s ease;
}

.pending-attachment-remove:hover {
  background: var(--color-palette-c36d4cdccdc9);
  border-color: var(--color-palette-c36d4cdccdc9);
  color: var(--color-palette-f2074b6cef37);
  transform: scale(1.1);
}

.pending-attachment-card--file .pending-attachment-remove {
  position: relative;
  top: 0;
  right: 0;
  background: var(--color-palette-b749cc259197);
  color: var(--text-primary);
  z-index: 10;
}

/* Image Editor Modal */
