}

.wallpaper-editor-toolbar-button--label { gap: 7px; padding-inline: 10px; }
.wallpaper-editor-toolbar-button--label span { font-size: var(--font-size-small); font-weight: var(--font-weight-semibold); }
.wallpaper-editor-adjustments { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px 18px; padding-top: 4px; }
.wallpaper-editor-range { display: grid; gap: 6px; min-width: 0; font-size: var(--font-size-small); color: var(--text-secondary); }
.wallpaper-editor-range > span { display: flex; justify-content: space-between; gap: 8px; }
.wallpaper-editor-range output { color: var(--text-primary); font-variant-numeric: tabular-nums; }
.wallpaper-editor-range input { width: 100%; accent-color: var(--accent-primary); }
.wallpaper-editor-footer { justify-content: flex-end; gap: 12px; padding: 14px 20px; }

@media (max-width: 520px) {
  .wallpaper-editor-backdrop { padding: 0; }
  .wallpaper-editor-modal { max-height: 100vh; min-height: 100vh; border: 0; border-radius: 0; }
  .wallpaper-editor-preview { min-height: 260px; }
