.wallpaper-editor-preview { height: 100%; min-height: 0; }
.wallpaper-editor-header { position: absolute; inset: 0 0 auto; z-index: 2; padding: max(12px, env(safe-area-inset-top)) 14px 12px; border: 0; background: linear-gradient(180deg, var(--color-palette-71b1e28a20b6), transparent); }
.wallpaper-editor-header h3, .wallpaper-editor-header p { display: none; }
.wallpaper-editor-icon-button, .wallpaper-editor-toolbar-button { background: var(--color-palette-5c1342314038); border-radius: var(--radius-pill); box-shadow: 0 3px 12px var(--color-palette-0bf61dd701cd); backdrop-filter: blur(8px); }
.wallpaper-editor-icon-button:hover, .wallpaper-editor-toolbar-button:hover:not(:disabled) { background: var(--color-palette-216cc9849058); color: var(--text-primary, var(--color-palette-f2074b6cef37)); transform: scale(1.08); }
.wallpaper-editor-controls { align-items: center; bottom: max(40px, calc(env(safe-area-inset-bottom) + 24px)); display: flex; gap: 10px; justify-content: center; left: 0; padding: 0 16px; position: absolute; right: 0; z-index: 3; border: 0; }
.wallpaper-editor-toolbar, .wallpaper-editor-zoom-value, .wallpaper-editor-toolbar-divider, .wallpaper-editor-toolbar-button--label { display: none; }
