    transform 220ms var(--motion-ease-exit, cubic-bezier(0.4, 0, 1, 1));
}

.image-lightbox-backdrop.is-closing {
  opacity: 0;
  transform: translate3d(0, 0, 0);
  transition:
    opacity 260ms var(--motion-ease-exit, cubic-bezier(0.4, 0, 1, 1)),
    transform 260ms var(--motion-ease-exit, cubic-bezier(0.4, 0, 1, 1));
}

.image-lightbox-backdrop.is-closing .image-lightbox-stage {
  opacity: 0;
  transform: scale(0.95);
  transition:
    opacity 260ms var(--motion-ease-exit, cubic-bezier(0.4, 0, 1, 1)),
