/* Google Calendar-style 3-hour step Today Timeline */
.plans-timeline {
  display: flex;
  flex-direction: column;
  position: relative;
  width: 100%;
}
.plans-timeline-slot {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr);
  min-height: 84px;
  position: relative;
}
.plans-timeline-slot:last-child {
