  color: var(--text-muted);
  display: flex;
  font-size: var(--font-size-caption);
  font-variant-numeric: tabular-nums;
  font-weight: var(--font-weight-semibold);
  justify-content: flex-end;
  padding-right: 6px;
  transform: translateY(-8px);
  user-select: none;
}
.plans-timeline-slot--allday .plans-timeline-time {
  font-size: var(--font-size-caption);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.plans-timeline-content {
  border-top: 1px solid color-mix(in srgb, var(--border-default) 70%, transparent);
  display: flex;
  flex-direction: column;
  min-height: inherit;
  min-width: 0;
  padding-bottom: 12px;
  padding-top: 6px;
  position: relative;
}
.plans-timeline-events {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}
.plans-timeline-events .plan-row {
  background: color-mix(in srgb, var(--surface-card) 60%, transparent);
  border: 1px solid color-mix(in srgb, var(--border-default) 60%, transparent);
  border-radius: var(--radius-surface);
  margin-bottom: 4px;
  grid-template-columns: minmax(0, 1fr);
  padding: 6px 8px;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}
.plans-timeline-events .plan-row:hover {
  background: color-mix(in srgb, var(--surface-card) 95%, transparent);
  border-color: color-mix(in oklab, var(--accent-primary) 35%, var(--border-default));
