.plans-month { display: grid; flex: 1; grid-template-columns: repeat(7, 1fr); min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 12px 8px; }
.plans-month button { border-bottom: 1px solid color-mix(in srgb, var(--border-default) 55%, transparent); position: relative; text-align: left; vertical-align: top; }
.plans-month i { background: var(--accent-primary); border-radius: var(--radius-circle); bottom: 12px; height: 5px; left: 50%; position: absolute; width: 5px; }
.plans-dialog-backdrop {
