.mobile-incoming-screen {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 30%, var(--color-palette-6bf3308fbb34) 0%, var(--color-palette-57f69fbbc5a7) 55%, var(--color-palette-a1ba515aed87) 100%);
