  padding-top: max(env(safe-area-inset-top, 0px), 52px);
}

.mobile-incoming-avatar-wrap {
  position: relative;
  width: 88px;
  height: 88px;
}

.mobile-incoming-ripple {
  position: absolute;
  border-radius: var(--radius-circle);
  border: 1.5px solid var(--color-palette-4083a2e3a50d);
  animation: mobile-ripple 2.6s ease-out infinite;
