}

/* ── Mobile active call screen (video off) ──────────────────────── */
.mobile-active-screen {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 28%, var(--color-palette-bc4f2b7623b8) 0%, var(--color-palette-43f6882724a0) 55%, var(--color-palette-f913db160a4f) 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  padding-top: max(env(safe-area-inset-top, 0px), 52px);
  padding-bottom: max(env(safe-area-inset-bottom, 0px), 132px);
  z-index: 5;
  pointer-events: auto;
}

.mobile-active-screen.mobile-active-screen--video {
  background: var(--color-palette-7b2817bf9b80);
  pointer-events: auto;
}

.mobile-active-screen.mobile-active-screen--video .mobile-active-controls {
  pointer-events: auto;
}

.mobile-active-screen--landscape {
  position: fixed;
  top: 0;
  left: 100vw;
  width: 100dvh;
  height: 100vw;
  padding: 0;
  transform: rotate(90deg);
  transform-origin: top left;
  z-index: 10000;
  overflow: hidden;
}
.mobile-active-screen--landscape .mobile-active-video-stage { inset: 0; }
.mobile-active-screen--landscape .mobile-active-controls { z-index: 35; }
.mobile-active-screen--landscape .mobile-active-top-bar { z-index: 40; }
.mobile-active-landscape-close { left: 12px; right: auto; }
.mobile-active-landscape-open { position: absolute; top: max(env(safe-area-inset-top, 0px), 16px); right: 16px; z-index: 32; display: grid; width: 40px; height: 40px; place-items: center; border: 1px solid var(--border-default); border-radius: var(--radius-circle); background: color-mix(in srgb, var(--surface-raised) 88%, transparent); color: var(--text-primary); }

.mobile-active-video-stage {
  position: absolute;
  inset: 0;
  background: var(--color-palette-7b2817bf9b80);
  pointer-events: auto;
}

.mobile-active-fullscreen-video {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.mobile-active-fullscreen-video--contain {
  object-fit: contain;
}

.mobile-active-screenshare-bar {
  position: absolute;
  top: max(env(safe-area-inset-top, 0px), 16px);
  left: 16px;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--color-palette-29d2b43c7e2e);
  border: 1px solid var(--color-palette-434a101cacc8);
  border-radius: var(--radius-pill);
  padding: 5px 12px 5px 10px;
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-medium);
  color: var(--color-palette-f2074b6cef37);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 2px 10px var(--color-palette-6190a6c871e7);
  pointer-events: auto;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.mobile-active-screenshare-dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-circle);
  background: var(--color-palette-7d1d1471da06);
  box-shadow: 0 0 6px var(--color-palette-3f2909676fa4);
}

.mobile-active-screenshare-stop-btn {
  background: var(--color-palette-79f8835a4739);
  color: var(--color-palette-f2074b6cef37);
  border: none;
  border-radius: var(--radius-pill);
  padding: 3px 9px;
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
