  display: inline-flex;
  align-items: center;
  box-shadow: 0 1px 4px var(--color-palette-279245c0d6e0);
}

.mobile-active-screenshare-stop-btn:active {
  transform: scale(0.94);
}

.mobile-active-pip-label {
  position: absolute;
  left: 6px;
  bottom: 6px;
  padding: 2px 6px;
  border-radius: var(--radius-small);
  background: var(--color-palette-f71fbab13810);
  color: var(--color-palette-f2074b6cef37);
  font-size: var(--font-size-micro);
  font-weight: var(--font-weight-medium);
  pointer-events: none;
}

.mobile-active-pip-video--contain {
  object-fit: contain !important;
}

.mobile-active-pip {
  position: absolute;
  width: 104px;
  height: 140px;
  border: 2px solid var(--color-palette-eafa2ab918ec);
  border-radius: var(--radius-control);
  box-shadow: 0 4px 18px var(--color-palette-86def6ffcd19);
  background: var(--color-palette-7b2817bf9b80);
  z-index: 20;
  overflow: hidden;
  cursor: pointer;
}

.mobile-active-pip > video {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.mobile-active-pip--top {
  top: max(calc(env(safe-area-inset-top, 0px) + 64px), 72px);
  bottom: auto;
}

.mobile-active-pip--bottom {
  top: auto;
  bottom: max(env(safe-area-inset-bottom, 0px), 12px);
}

.mobile-active-pip--left {
  left: 12px;
  right: auto;
}

.mobile-active-pip--right {
  left: auto;
  right: 12px;
}

.mobile-active-pip--top.mobile-active-pip--right {
  /* Clear the top-right minimise button. */
  top: max(calc(env(safe-area-inset-top, 0px) + 64px), 72px);
}

.mobile-active-pip-flip {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: var(--radius-circle);
  display: grid;
  place-items: center;
  color: var(--color-palette-f2074b6cef37);
  background: var(--color-palette-5611d9915638);
  cursor: pointer;
}

.mobile-active-pip-flip svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.mobile-active-top-bar {
  position: absolute;
  top: max(env(safe-area-inset-top, 0px), 16px);
  right: 16px;
  z-index: 25;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: opacity 0.2s ease, transform 0.2s ease;
}
.mobile-active-top-bar:has(.mobile-active-invite-btn) {
  left: 16px;
  right: 16px;
  justify-content: space-between;
}
.mobile-active-top-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }
.mobile-active-top-actions .mobile-active-landscape-open {
  position: static;
  inset: auto;
  flex: 0 0 40px;
  width: 40px;
  height: 40px;
  z-index: auto;
}

.mobile-active-top-bar.mobile-active-controls--hidden {
  opacity: 0;
  pointer-events: none;
  transform: translateY(-8px);
}

.mobile-active-shrink-btn {
  flex: 0 0 40px;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-circle);
  background: var(--color-palette-554de51a1e86);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: var(--color-palette-f2074b6cef37);
  border: 1px solid var(--color-palette-5089217ef21a);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 2px 10px var(--color-palette-279245c0d6e0);
}

.mobile-active-shrink-btn:active {
  transform: scale(0.92);
}

.mobile-active-notice-banner {
  position: absolute;
  top: calc(max(env(safe-area-inset-top, 0px), 16px) + 48px);
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-palette-c06e52c47be6);
  color: var(--color-palette-f2074b6cef37);
  border: 1px solid var(--color-palette-5089217ef21a);
  border-radius: var(--radius-pill);
  padding: 8px 18px;
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-medium);
  z-index: 50;
  box-shadow: 0 4px 18px var(--color-palette-4c85ca9b7179);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: none;
  animation: voice-notice-pop 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  text-align: center;
  max-width: 85%;
}

.mobile-active-proximity-blank {
  position: absolute;
  inset: 0;
  z-index: 50;
  background: var(--color-palette-7b2817bf9b80);
  pointer-events: none;
}

.mobile-active-avatar-wrap {
  position: relative;
  width: 88px;
  height: 88px;
}

.mobile-active-audio-ring {
  position: absolute;
  border-radius: var(--radius-circle);
  border: 1.5px solid var(--color-palette-434a101cacc8);
  animation: call-audio-pulse 1.5s ease-in-out infinite;
}

.mobile-active-audio-ring:nth-child(1) { inset: -14px; animation-delay: 0s; }
.mobile-active-audio-ring:nth-child(2) { inset: -26px; animation-delay: 0.3s; }

.mobile-active-audio-ring.silent {
  animation: none;
  opacity: 0;
}

.mobile-active-avatar {
  position: relative;
  z-index: 2;
  width: 88px;
  height: 88px;
  border-radius: var(--radius-circle);
  background: linear-gradient(140deg, var(--color-palette-c5c97d3b3428), var(--color-palette-3ed7764068c1));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-display-small);
  font-weight: var(--font-weight-bold);
  color: var(--color-palette-f2074b6cef37);
  border: 2px solid var(--color-palette-d635c939daff);
  overflow: hidden;
}

.mobile-active-name {
  font-size: var(--font-size-body-large);
  font-weight: var(--font-weight-semibold);
  color: var(--color-palette-f2074b6cef37);
  margin-top: 14px;
}

.mobile-active-time {
  font-size: var(--font-size-caption);
  color: var(--color-palette-3d92bff672e9);
  margin-top: 4px;
}

.mobile-active-waveform {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  margin-top: 12px;
  height: 24px;
}

.mobile-active-wave-bar {
  width: 3px;
  border-radius: var(--radius-small);
  background: var(--color-palette-09ed3334d65d);
  animation: call-wave 1.1s ease-in-out infinite;
}

.mobile-active-wave-bar:nth-child(1) { height:  5px; animation-delay: 0.00s; }
.mobile-active-wave-bar:nth-child(2) { height: 13px; animation-delay: 0.10s; }
.mobile-active-wave-bar:nth-child(3) { height: 20px; animation-delay: 0.20s; }
.mobile-active-wave-bar:nth-child(4) { height: 11px; animation-delay: 0.30s; }
.mobile-active-wave-bar:nth-child(5) { height: 16px; animation-delay: 0.15s; }
.mobile-active-wave-bar:nth-child(6) { height:  7px; animation-delay: 0.25s; }
.mobile-active-wave-bar:nth-child(7) { height: 17px; animation-delay: 0.05s; }

.mobile-active-wave-bar.silent {
  animation: none !important;
  height: 3px !important;
  opacity: 0.2;
  background: var(--color-palette-9fd3860e0ba9);
}

/* Controls overlay at the bottom of mobile active screen */
.mobile-active-controls {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px 24px max(env(safe-area-inset-bottom, 0px), 28px);
  background: linear-gradient(transparent, var(--color-palette-9639b8bea79a));
  display: flex;
  justify-content: center;
  gap: 14px;
  flex-wrap: wrap;
  z-index: 10;
  opacity: 1;
  transition: opacity 180ms ease;
}

.mobile-active-controls--hidden {
  opacity: 0;
  pointer-events: none;
}

.mobile-active-ctrl {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}

.mobile-active-ctrl-btn {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-circle);
  background: var(--color-palette-b749cc259197);
  border: 1px solid var(--color-palette-4abb7e8c1277);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--color-palette-f2074b6cef37);
  transition: all 0.15s ease;
}

.mobile-active-ctrl-btn.muted {
  background: var(--color-palette-2f2358b27e2f);
  color: var(--color-palette-e2e7fd8240e1);
}

.mobile-active-ctrl-btn.active {
  background: var(--accent-primary);
  border-color: var(--accent-primary);
  color: var(--color-palette-f2074b6cef37);
}

.mobile-active-ctrl-btn.end {
  background: var(--color-palette-79f8835a4739);
  border-color: transparent;
}

button.mobile-active-ctrl-btn.end:hover:not(:disabled),
button.mobile-active-ctrl-btn.end:active:not(:disabled) {
  background: var(--color-palette-79f8835a4739);
  border-color: transparent;
  color: var(--color-palette-f2074b6cef37);
  opacity: 1;
  transform: none;
}

.mobile-active-ctrl-btn svg {
  width: 18px;
  height: 18px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.mobile-active-ctrl-btn.end svg {
  fill: var(--color-palette-f2074b6cef37);
  stroke: none;
}

.mobile-active-ctrl-lbl {
  font-size: var(--font-size-micro);
  color: var(--color-palette-9cc55b664ed9);
}

/* ── Meeting Intelligence Popover (Pattern A) ─────────────────────── */
.meeting-intel-popover {
  position: absolute;
  bottom: calc(100% + 14px);
  left: 50%;
  transform: translateX(-50%);
  width: 336px;
  max-width: 90vw;
  background: color-mix(in oklab, var(--surface-raised) 92%, var(--color-palette-a5c680c34877));
  backdrop-filter: blur(24px) saturate(1.12);
  -webkit-backdrop-filter: blur(24px) saturate(1.12);
  border: 1px solid color-mix(in oklab, var(--border-default) 70%, transparent);
  border-radius: var(--radius-panel);
  box-shadow: var(--float-shadow-strong), 0 1px 0 var(--color-palette-c34f5a2a4d80) inset;
  z-index: 1000;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  animation: intelPopoverFadeIn 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  color: var(--color-palette-f2074b6cef37);
}

@keyframes intelPopoverFadeIn {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(8px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0) scale(1);
  }
}

.meeting-intel-popover--mobile {
  position: fixed;
  bottom: 80px;
  left: 50%;
  transform: translateX(-50%);
  width: calc(100vw - 32px);
  max-width: 360px;
}

.meeting-intel-popover--anchored {
  bottom: auto;
  max-width: min(336px, calc(100vw - 32px));
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  transform: none;
  animation: intelPopoverAnchoredFadeIn 0.18s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes intelPopoverAnchoredFadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}

.meeting-intel-background-toast {
  align-items: center;
  background: color-mix(in oklab, var(--surface-raised) 94%, var(--color-palette-a5c680c34877));
  border: 1px solid color-mix(in oklab, var(--accent-primary) 34%, var(--border-default));
  border-radius: var(--radius-bubble);
  bottom: auto;
  box-shadow: var(--float-shadow-strong), 0 1px 0 var(--color-palette-c34f5a2a4d80) inset;
  color: var(--text-primary);
  display: flex;
  gap: 10px;
  left: 50%;
  max-width: min(360px, calc(100vw - 32px));
  padding: 10px 14px 10px 10px;
  position: fixed;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 1200;
  animation: meeting-intel-toast-in .22s cubic-bezier(.16, 1, .3, 1);
}

.meeting-intel-background-toast-icon {
  align-items: center;
  background: color-mix(in oklab, var(--accent-primary) 18%, var(--surface-card));
  border-radius: var(--radius-circle);
  color: var(--accent-primary);
  display: inline-flex;
  flex: 0 0 34px;
  height: 34px;
  justify-content: center;
}

.meeting-intel-background-toast > span:last-child { display: grid; gap: 2px; }
.meeting-intel-background-toast strong { font-size: var(--font-size-caption); }
.meeting-intel-background-toast small { color: var(--text-tertiary); font-size: var(--font-size-caption); }

@keyframes meeting-intel-toast-in {
  from { opacity: 0; transform: translate(-50%, calc(-50% + 8px)) scale(.96); }
  to { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

.meeting-intel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 8px 4px;
}

.meeting-intel-title-row {
