.message-bubble.mine .audio-player-eq span,
.message-bubble.mine .audio-player-wave-fill {
  background: var(--color-palette-f2074b6cef37);
}

.message-bubble.mine .audio-player-wave::before {
  background: var(--color-palette-c4d49fe1b2f3);
}

.message-bubble.mine .audio-player-time,
.message-bubble.mine .audio-player-title,
.message-bubble.mine .audio-player-status {
  color: var(--color-palette-58218d7102c6);
}

.audio-player--compact {
  align-items: center;
}

.audio-player-controls {
  align-items: center;
  display: grid;
  gap: 8px;
  grid-template-columns: 28px minmax(0, 1fr);
  min-width: 0;
}

.audio-player.is-session-active,
.audio-player[data-session-active="true"] {
  border-color: color-mix(in oklab, var(--accent-primary) 70%, var(--border-default));
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--accent-primary) 22%, transparent);
}

.audio-player.is-playing {
  border-color: var(--accent-primary);
}

.audio-player-body {
  display: grid;
  gap: 4px;
  min-width: 0;
  position: relative;
}

.audio-player-wave-row {
  align-items: center;
  display: grid;
  gap: 8px;
  grid-template-columns: auto minmax(0, 1fr);
  min-width: 0;
  padding-right: 18px;
}

.audio-player-eq {
  align-items: flex-end;
  display: inline-flex;
  gap: 2px;
  height: 12px;
  opacity: 0.45;
}

.audio-player-eq span {
  background: var(--accent-primary);
  border-radius: var(--radius-pill);
  display: block;
  height: 4px;
  transform-origin: bottom;
  width: 2px;
}

.audio-player-eq.is-active {
  opacity: 1;
}

.audio-player-eq.is-active span:nth-child(1) {
  animation: audio-eq-bar 0.9s ease-in-out infinite;
}
.audio-player-eq.is-active span:nth-child(2) {
  animation: audio-eq-bar 0.9s ease-in-out 0.12s infinite;
}
.audio-player-eq.is-active span:nth-child(3) {
  animation: audio-eq-bar 0.9s ease-in-out 0.24s infinite;
}
.audio-player-eq.is-active span:nth-child(4) {
  animation: audio-eq-bar 0.9s ease-in-out 0.06s infinite;
}

@keyframes audio-eq-bar {
  0%,
  100% {
    height: 3px;
  }
  50% {
    height: 12px;
  }
}

.audio-player-wave {
  background: transparent;
  border-radius: var(--radius-pill);
  cursor: pointer;
  height: 28px;
  margin-left: 6px;
  min-width: 0;
  overflow: visible;
  position: relative;
  touch-action: none;
  width: 100%;
}

.audio-player-wave:hover {
  cursor: pointer;
}

.audio-player-wave::before {
  background: color-mix(in oklab, var(--border-default) 70%, transparent);
  border-radius: var(--radius-pill);
  content: "";
  height: 6px;
  left: 0;
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
}

.audio-player-wave[aria-disabled="true"] {
  cursor: default;
  opacity: 0.5;
}

.audio-player-wave[aria-disabled="true"][data-idle="true"] {
  opacity: 1;
}

.audio-player-wave-fill {
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--accent-primary) 80%, var(--color-palette-4cea3afb98e3)),
    var(--accent-primary)
  );
  border-radius: var(--radius-pill);
  color: var(--accent-primary);
  display: block;
  height: 6px;
  max-width: 100%;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  transition: width 80ms linear;
  z-index: 1;
}

.audio-player-wave-fill::after {
  background: currentColor;
  border: 2px solid var(--surface-card);
  border-radius: var(--radius-circle);
  box-shadow: 0 1px 4px color-mix(in oklab, var(--color-palette-7b2817bf9b80) 35%, transparent);
  content: "";
  height: 12px;
  position: absolute;
  right: -6px;
  top: 50%;
  transform: translateY(-50%);
  transition: transform 120ms ease;
  width: 12px;
}

.audio-player-wave:hover .audio-player-wave-fill::after,
.audio-player-wave:active .audio-player-wave-fill::after {
  transform: translateY(-50%) scale(1.25);
}

.message-bubble.mine .audio-player-wave-fill::after {
  border-color: color-mix(in oklab, var(--bubble-outgoing) 88%, var(--color-palette-7b2817bf9b80));
  color: var(--color-palette-f2074b6cef37);
}

.audio-player-meta-row {
  align-items: center;
  display: flex;
  gap: 8px;
  justify-content: space-between;
  min-width: 0;
}

.audio-player-title {
  color: var(--text-secondary);
  flex: 1 1 auto;
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-medium);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.audio-player-play-pause {
  align-items: center;
  background: var(--accent-primary);
  border: 0;
  border-radius: var(--radius-circle);
  color: var(--color-palette-f2074b6cef37);
  cursor: pointer;
  display: inline-flex;
  height: 28px;
  justify-content: center;
  min-height: 28px;
  min-width: 28px;
  padding: 0;
  position: relative;
  transition: background-color 150ms ease-out, transform 150ms ease-out, box-shadow 180ms ease-out;
  width: 28px;
}

.audio-player-play-pulse {
  border: 1.5px solid color-mix(in oklab, var(--accent-primary) 70%, var(--color-palette-4cea3afb98e3));
  border-radius: var(--radius-circle);
  inset: -3px;
  opacity: 0;
  pointer-events: none;
  position: absolute;
}

.audio-player-play-pause.is-playing .audio-player-play-pulse {
  animation: audio-play-pulse 1.4s ease-out infinite;
}

.audio-player-play-pause.is-loading {
  opacity: 0.72;
}

@keyframes audio-play-pulse {
  0% {
    opacity: 0.55;
    transform: scale(0.92);
  }
  70% {
    opacity: 0;
    transform: scale(1.35);
  }
  100% {
    opacity: 0;
    transform: scale(1.35);
  }
}

.audio-player-play-pause:active:not(:disabled) {
  transform: scale(0.94);
}

.audio-player-play-pause:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.audio-player-time {
  color: var(--text-secondary);
  font-size: var(--font-size-caption);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.audio-player-status,
.audio-player-error,
.audio-restore-status {
  font-size: var(--font-size-caption);
  grid-column: 1 / -1;
  line-height: 1.2;
}

.audio-player-error {
  align-items: center;
  color: var(--danger);
  display: flex;
  gap: 6px;
}

.audio-player-retry {
  background: transparent;
  border: 1px solid var(--border-default);
  border-radius: var(--radius-control);
  color: var(--text-primary);
  cursor: pointer;
  font-size: var(--font-size-caption);
  padding: 2px 8px;
}

.audio-player button {
  min-height: 0;
}

.audio-player button:focus-visible,
.audio-player input:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

/* Transcribe button in audio player (in meta row) */
.audio-player-transcribe-btn {
  align-items: center;
  aspect-ratio: 1 / 1;
  background: color-mix(in oklab, var(--accent-primary) 12%, transparent);
  border: 1px solid color-mix(in oklab, var(--accent-primary) 28%, transparent);
  border-radius: var(--radius-circle);
  box-sizing: border-box;
  color: var(--accent-primary);
