/* --- Group Call Active Banner & Pre-Join Modal Styles --- */
.group-call-active-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 16px;
  background: linear-gradient(135deg, var(--color-palette-7e7729dc444a), var(--color-palette-90517c14c155));
  border-bottom: 1px solid var(--color-palette-0ba5a1d5f3b0);
  backdrop-filter: blur(12px);
  color: var(--text-primary);
  z-index: 20;
}

.group-call-banner-info {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.group-call-banner-pulse {
  width: 10px;
  height: 10px;
  border-radius: var(--radius-circle);
  background-color: var(--color-palette-8b8f7c3d4541);
  box-shadow: 0 0 0 0 var(--color-palette-deb9630dd5a3);
  animation: group-call-pulse-ring 1.8s infinite;
  flex: 0 0 auto;
}

@keyframes group-call-pulse-ring {
  0% {
    box-shadow: 0 0 0 0 var(--color-palette-deb9630dd5a3);
  }
  70% {
    box-shadow: 0 0 0 8px var(--color-palette-97fa8c51b2ce);
  }
  100% {
    box-shadow: 0 0 0 0 var(--color-palette-97fa8c51b2ce);
  }
}

.group-call-banner-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.group-call-banner-title {
  font-weight: var(--font-weight-semibold);
  font-size: var(--font-size-small);
  color: var(--color-palette-8b8f7c3d4541);
}

.group-call-banner-subtitle {
  font-size: var(--font-size-caption);
  opacity: 0.75;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.group-call-banner-join-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--color-palette-8b8f7c3d4541);
  color: var(--color-palette-f2074b6cef37);
  border: 0;
  border-radius: var(--radius-pill);
  padding: 6px 14px;
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: all 0.15s ease;
  box-shadow: 0 2px 8px var(--color-palette-0ba5a1d5f3b0);
}

.group-call-banner-join-btn:hover {
  background: var(--color-palette-3c5c1ab6c5fd);
  transform: translateY(-1px);
}

.group-call-join-svg {
  width: 16px;
  height: 16px;
}

/* Pre-Join Approval Modal */
.group-call-prejoin-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
