/* Android active-chat surface: the viewport is fixed; only the message history scrolls. */
@media (max-width: 960px) {
  :root[data-platform="native"] .messenger-shell.has-active-chat {
    height: 100dvh;
    max-height: 100dvh;
    overflow: hidden;
    overscroll-behavior: none;
  }

  :root[data-platform="native"] .messenger-shell.has-active-chat .chat-detail-header--floating::before {
    background: linear-gradient(to bottom, var(--color-palette-7b2817bf9b80) 0%, var(--color-palette-190bdc64d2dc) 100%);
    content: "";
    height: calc(100% + max(20px, env(safe-area-inset-top)));
    inset: calc(-1 * max(20px, env(safe-area-inset-top))) -10px auto;
    pointer-events: none;
    position: absolute;
    z-index: -1;
  }

  :root[data-platform="native"] .messenger-shell.has-active-chat .messages-panel {
    overflow-y: auto;
    overscroll-behavior-y: contain;
  }
}

/* Persistent bottom navigation for every mobile app section. Active chats are
   intentionally excluded: their conversation controls own the full screen. */
@media (max-width: 960px) {
  .app-frame:not(.has-active-chat) > .app-nav {
    bottom: var(--nav-pill-inset-bottom);
    display: flex;
    position: fixed;
    z-index: 100;
  }

  .storage-page .storage-layout,
  .plans-page .plans-layout,
  .settings-page > .page-surface,
  .admin-page > .page-surface,
  .contacts-page > .page-surface {
    padding-bottom: calc(var(--nav-pill-height) + var(--nav-pill-inset-bottom) + 32px);
  }
}

/* Capacitor reports a native viewport independently of its CSS-pixel width.
   Keep its section navigation in its mobile form even when Android WebView
   reports a width greater than the responsive breakpoint. */
:root[data-platform="native"] .app-frame:not(.has-active-chat) > .app-nav {
  align-items: center;
  background: transparent;
  border: 0;
  border-radius: var(--radius-pill);
  bottom: var(--nav-pill-inset-bottom);
  box-shadow: var(--nav-pill-shadow);
  display: flex !important;
  flex-direction: row;
  gap: 6px;
  height: var(--nav-pill-height);
  justify-content: space-around;
  left: var(--nav-pill-inset-x);
  min-height: auto;
  padding: 6px 8px;
  position: fixed;
  right: var(--nav-pill-inset-x);
  top: auto;
  width: auto;
  z-index: 100;
}

:root[data-platform="native"] .app-frame:not(.has-active-chat) > .app-nav .app-nav-links {
  display: flex;
  flex: 1;
  gap: 0;
}

:root[data-platform="native"] .app-frame:not(.has-active-chat) > .app-nav .app-nav-links > a {
  flex: 1;
}

:root[data-platform="native"] .app-frame:not(.has-active-chat) > .app-nav a {
  display: grid;
  justify-items: center;
  max-height: none;
  max-width: none;
  min-height: 56px;
}

:root[data-platform="native"] .app-frame:not(.has-active-chat) > .app-nav .app-brand,
:root[data-platform="native"] .app-frame:not(.has-active-chat) > .app-nav .app-nav-logout {
  display: none;
}

:root[data-platform="native"] .storage-page .storage-layout,
:root[data-platform="native"] .plans-page .plans-layout,
:root[data-platform="native"] .settings-page > .page-surface,
:root[data-platform="native"] .admin-page > .page-surface {
  padding-bottom: calc(var(--nav-pill-height) + var(--nav-pill-inset-bottom) + 32px);
}

