nd .2s ease; width: 45px; }.plugin-switch span::after { background: var(--color-palette-a86da059edb2); border-radius: var(--radius-circle); content: ""; height: 19px; left: 3px; position: absolute; top: 3px; transition: transform .2s ease; width: 19px; }.plugin-switch input:checked + span { background: var(--color-palette-c02be1992166); }.plugin-switch input:checked + span::after { transform: translateX(20px); }.plugin-switch input:focus-visible + span { outline: 2px solid var(--color-palette-93bdd100c753); outline-offset: 3px; }.plugin-switch input:disabled + span { cursor: progress; opacity: .55; }

