  white-space: nowrap;
}
.canvas-card-bubble-subtitle {
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-medium);
  color: var(--color-palette-e93a99255bf5);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.canvas-card-bubble-open-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: var(--color-palette-c34f5a2a4d80);
