/* Shared compact back control. Individual pages may position it, but never restyle it. */
.back-button {
  align-items: center;
  background: var(--color-palette-db051e710650);
  border: 1px solid var(--color-palette-19c8cd6ac63b);
  border-radius: var(--radius-circle);
  box-sizing: border-box;
  color: var(--color-palette-f2074b6cef37);
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 32px;
  height: 32px;
  justify-content: center;
  min-height: 32px;
  min-width: 32px;
  padding: 0;
  text-decoration: none;
  transition: background-color 160ms ease, border-color 160ms ease, transform 160ms ease;
  width: 32px;
}

.back-button:hover:not(:disabled) { background: var(--color-palette-6ac3dda04bda); border-color: var(--color-palette-8838f37cda32); color: var(--color-palette-f2074b6cef37); }
.back-button:active:not(:disabled) { transform: scale(.96); }
.back-button:focus-visible { outline: 2px solid var(--accent-primary); outline-offset: 2px; }
.back-button > svg { height: 18px; width: 18px; }

.chat-detail-header .back-button.mobile-back-button { display: none; }
@media (max-width: 680px) { .chat-detail-header .back-button.mobile-back-button { display: inline-flex; } }

/* ── Global Quick Switcher (Ctrl+K) ────────────────────────────────────────── */
.quick-switcher-backdrop {
  place-items: start center;
  z-index: 10000;
  background: var(--color-palette-0f153bff29ca);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: min(100px, 12vh);
  padding-left: 16px;
  padding-right: 16px;
}

.popup-dialog.quick-switcher-modal {
