.checklist-card-category-badge {
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  color: var(--text-secondary);
  text-transform: capitalize;
}

.checklist-card-open-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: color-mix(in oklab, var(--accent-primary) 15%, transparent);
  color: var(--accent-primary);
  border: 1px solid color-mix(in oklab, var(--accent-primary) 30%, transparent);
  border-radius: var(--radius-pill);
  padding: 4px 10px;
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  min-height: auto;
  transition: background 0.15s ease, border-color 0.15s ease;
  flex-shrink: 0;
}

.checklist-card-open-btn:hover {
  background: var(--accent-primary);
  color: var(--accent-contrast, var(--color-palette-f2074b6cef37));
}

/* Progress bar in chat card */
.checklist-card-progress {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 8px 0 6px;
}

.checklist-card-progress-bar {
  width: 100%;
  height: 6px;
  border-radius: var(--radius-pill);
  background: color-mix(in oklab, var(--border-default, var(--color-palette-7df944bad1e2)) 70%, transparent);
  overflow: hidden;
}

.checklist-card-progress-fill {
  height: 100%;
  border-radius: var(--radius-pill);
  background: var(--accent-primary);
  transition: width 0.25s ease-out;
}

.checklist-card-progress-text {
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  color: var(--text-secondary);
  text-align: right;
}

/* Items in card */
.checklist-card-items {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 4px 0 8px;
  max-height: 280px;
  overflow-y: auto;
}

.checklist-card-section {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-top: 4px;
}

.checklist-card-section-title {
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-bold);
  color: var(--text-secondary);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 3px 6px 1px;
}

.checklist-card-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border-radius: var(--radius-control);
  transition: background 0.12s ease;
}

.checklist-card-item:hover {
  background: color-mix(in oklab, var(--text-primary) 5%, transparent);
}

.checklist-card-check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 0;
  padding: 0;
  cursor: pointer;
  color: var(--text-secondary);
  flex-shrink: 0;
  line-height: 0;
}

.checklist-card-check:hover {
  color: var(--accent-primary);
}

.checklist-card-item.is-completed .checklist-card-check {
  color: var(--accent-primary);
}

.checklist-card-item-text {
  font-size: var(--font-size-small);
  color: var(--text-primary);
  line-height: 1.35;
  word-break: break-word;
  transition: color 0.15s ease, text-decoration 0.15s ease;
}

.checklist-card-item.is-completed .checklist-card-item-text {
  color: var(--text-secondary);
  text-decoration: line-through;
  opacity: 0.72;
}

/* Quick adder in chat card */
.checklist-card-quick-add {
  display: flex;
  align-items: center;
  gap: 6px;
  padding-top: 6px;
  border-top: 1px solid color-mix(in oklab, var(--border-default, var(--color-palette-7df944bad1e2)) 50%, transparent);
}

.checklist-card-add-input {
  flex: 1;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  min-height: unset !important;
  height: auto !important;
  padding: 4px 8px !important;
  font-size: var(--font-size-small);
  color: var(--text-primary);
  outline: none !important;
}

.checklist-card-add-input:focus {
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}

.checklist-card-add-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-control);
  background: var(--accent-primary);
  color: var(--accent-contrast, var(--color-palette-f2074b6cef37));
  border: 0;
  cursor: pointer;
  flex-shrink: 0;
}

.checklist-card-add-btn:hover {
  filter: brightness(1.1);
}

/* Rich Checklist Creator (Attachment Sheet Tab) */
.rich-checklist-creator {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 8px 4px;
}

.checklist-creator-header {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.checklist-category-selector {
  display: flex;
  gap: 8px;
}

.checklist-cat-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: var(--radius-pill);
  background: var(--surface-raised, var(--color-palette-1b686cf980de));
  border: 1px solid var(--border-default, var(--color-palette-231a4959a5d3));
  color: var(--text-secondary);
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: all 0.15s ease;
}

.checklist-cat-pill:hover {
  color: var(--text-primary);
  border-color: var(--accent-primary);
}

.checklist-cat-pill.active {
  background: color-mix(in oklab, var(--accent-primary) 18%, var(--surface-raised));
  border-color: var(--accent-primary);
  color: var(--accent-primary);
}

.checklist-template-packs {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.checklist-template-label {
  font-size: var(--font-size-caption);
  color: var(--text-secondary);
  font-weight: var(--font-weight-semibold);
}

.checklist-template-pack-btn {
  background: color-mix(in oklab, var(--surface-raised) 70%, transparent);
  border: 1px dashed var(--border-default, var(--color-palette-231a4959a5d3));
  border-radius: var(--radius-pill);
  padding: 4px 10px;
  font-size: var(--font-size-caption);
  color: var(--text-primary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.checklist-template-pack-btn:hover {
  border-color: var(--accent-primary);
  color: var(--accent-primary);
}

.checklist-creator-input-row {
  display: flex;
  gap: 8px;
}

.checklist-creator-input {
  flex: 1;
  background: var(--surface-raised, var(--color-palette-1b686cf980de));
  border: 1px solid var(--border-default, var(--color-palette-231a4959a5d3));
  border-radius: var(--radius-surface);
  padding: 8px 12px;
  color: var(--text-primary);
  font-size: var(--font-size-small);
  outline: none;
}

.checklist-creator-input:focus {
  border-color: var(--accent-primary);
}

.checklist-creator-section-input {
  max-width: 130px;
}

.checklist-creator-items-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 220px;
  overflow-y: auto;
  padding: 4px 0;
}

.checklist-creator-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: color-mix(in oklab, var(--surface-raised) 50%, transparent);
  border: 1px solid var(--border-default, var(--color-palette-7df944bad1e2));
  border-radius: var(--radius-control);
  padding: 6px 10px;
  font-size: var(--font-size-small);
  color: var(--text-primary);
}

.checklist-creator-item-sec {
  font-size: var(--font-size-caption);
  color: var(--accent-primary);
  background: color-mix(in oklab, var(--accent-primary) 12%, transparent);
  padding: 2px 6px;
  border-radius: var(--radius-small);
  margin-left: 6px;
}

.checklist-creator-item-del {
  background: transparent;
  border: 0;
  color: var(--text-secondary);
  cursor: pointer;
  display: inline-flex;
  padding: 2px;
}

.checklist-creator-item-del:hover {
  color: var(--color-palette-c36d4cdccdc9);
}

.checklist-creator-submit-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: var(--accent-primary);
  color: var(--accent-contrast, var(--color-palette-f2074b6cef37));
  border: 0;
  border-radius: var(--radius-surface);
  padding: 10px 16px;
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-bold);
  cursor: pointer;
  margin-top: 6px;
  transition: filter 0.15s ease;
}

.checklist-creator-submit-btn:hover {
  filter: brightness(1.08);
}

/* Notion-Style Checklist Page */
.checklist-page {
  background: var(--canvas-amoled, var(--color-palette-f81dba7624f5));
  color: var(--text-primary);
  min-height: 100dvh;
  padding: 20px 24px;
}

.checklist-header {
  align-items: flex-start;
  gap: 16px;
}

.checklist-header-info {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.checklist-category-pills {
  display: flex;
  gap: 6px;
}

.checklist-progress-container {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
  margin: 0 0 16px;
  background: var(--color-palette-cd7f1fae966d);
  border: 1px solid var(--color-palette-fef646fa4c37);
  border-radius: var(--radius-surface);
  padding: 12px 16px;
  box-sizing: border-box;
}

.checklist-progress-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: var(--font-size-small);
}

.checklist-progress-stat {
  color: var(--text-secondary);
}

.checklist-progress-percent {
  font-weight: var(--font-weight-bold);
  color: var(--accent-primary);
}

.checklist-progress-track {
  width: 100%;
  height: 8px;
  border-radius: var(--radius-pill);
  background: var(--color-palette-e2c14cd6188a);
  overflow: hidden;
}

.checklist-workspace {
  display: flex;
  flex-direction: column;
  gap: 18px;
  width: 100%;
}

.checklist-section-block {
  background: var(--color-palette-daee30a9d932);
  border: 1px solid var(--color-palette-e161afe86fb2);
  border-radius: var(--radius-surface);
  padding: 14px 18px;
}

.checklist-section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 8px;
  margin-bottom: 6px;
  border-bottom: 1px solid var(--color-palette-e161afe86fb2);
}

.checklist-section-title {
  font-size: var(--font-size-body);
  font-weight: var(--font-weight-bold);
  color: var(--accent-primary);
  letter-spacing: 0.02em;
}

.checklist-section-count {
  font-size: var(--font-size-caption);
  color: var(--text-secondary);
}

.checklist-section-items {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.checklist-item-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 6px;
  border-radius: var(--radius-control);
  transition: background 0.12s ease;
}

.checklist-item-row:hover {
  background: var(--color-palette-69142783e8a3);
}

.checklist-item-row:hover .checklist-item-delete-btn {
  opacity: 1;
}

.checklist-item-check-btn {
  background: transparent;
  border: 0;
  cursor: pointer;
  display: inline-flex;
  padding: 0;
  color: var(--text-secondary);
  line-height: 0;
}

.checklist-item-check-btn .icon-checked {
  color: var(--accent-primary);
}

.checklist-item-text-input {
  flex: 1;
  background: transparent;
  border: 0;
  border-bottom: 1px solid transparent;
  color: var(--text-primary);
  font-size: var(--font-size-body);
  font-family: inherit;
  padding: 4px 0;
  outline: none;
  transition: border-color 0.15s ease;
}

.checklist-item-text-input:focus {
  border-bottom-color: var(--accent-primary);
}

.checklist-item-row.completed .checklist-item-text-input {
  color: var(--text-secondary);
  text-decoration: line-through;
  opacity: 0.65;
}

.checklist-item-delete-btn {
  background: transparent;
  border: 0;
  color: var(--text-secondary);
  cursor: pointer;
  opacity: 0;
  display: inline-flex;
  padding: 4px;
  border-radius: var(--radius-control);
  transition: opacity 0.15s ease, color 0.15s ease;
}

.checklist-item-delete-btn:hover {
  color: var(--color-palette-c36d4cdccdc9);
}

.checklist-add-item-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 0;
  color: var(--text-secondary);
  font-size: var(--font-size-small);
  cursor: pointer;
  padding: 8px 6px 2px;
  margin-top: 4px;
  transition: color 0.15s ease;
}

.checklist-add-item-btn:hover {
  color: var(--text-secondary);
}

.checklist-footer-actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 8px;
}

.checklist-action-buttons {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.checklist-action-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--color-palette-3f96bb6723a3);
  border: 1px solid var(--color-palette-a42748894dd7);
  border-radius: var(--radius-pill);
  padding: 8px 14px;
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
  color: var(--text-primary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.checklist-action-pill:hover {
  border-color: var(--accent-primary);
  color: var(--accent-primary);
}

.checklist-action-pill.highlight {
  background: color-mix(in oklab, var(--accent-primary) 12%, var(--color-palette-3f96bb6723a3));
  border-color: var(--accent-primary);
  color: var(--accent-primary);
}

.checklist-new-section-form {
  display: flex;
  gap: 8px;
  align-items: center;
}

.checklist-new-section-input {
  flex: 1;
  background: var(--color-palette-3f96bb6723a3);
  border: 1px solid var(--accent-primary);
  border-radius: var(--radius-control);
  padding: 8px 12px;
  color: var(--text-primary);
  font-size: var(--font-size-small);
  outline: none;
}

.checklist-btn-primary {
  background: var(--accent-primary);
  color: var(--accent-contrast, var(--color-palette-f2074b6cef37));
  border: 0;
  border-radius: var(--radius-control);
  padding: 8px 14px;
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-bold);
  cursor: pointer;
}

.checklist-btn-secondary {
  background: var(--color-palette-4daf861ca303);
  color: var(--text-primary);
  border: 0;
  border-radius: var(--radius-control);
  padding: 8px 14px;
  font-size: var(--font-size-small);
  cursor: pointer;
}

/* Admin Plugin Preview for Checklist */
.plugin-preview--checklist {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px;
  justify-content: center;
}

.plugin-checklist-line {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: var(--font-size-small);
  color: var(--text-secondary);
}

.plugin-checklist-line.is-checked {
  color: var(--text-primary);
}

.plugin-checklist-line.is-checked span:last-child {
  text-decoration: line-through;
  opacity: 0.7;
}

.plugin-check-box {
  width: 14px;
  height: 14px;
  border-radius: var(--radius-small);
  border: 1px solid var(--border-default, var(--color-palette-d958fc46830a));
  display: inline-block;
  flex-shrink: 0;
}

.plugin-checklist-line.is-checked .plugin-check-box {
  background: var(--accent-primary);
  border-color: var(--accent-primary);
}

