/* ==========================================================================
   Shared Checklist Plugin Styles
   ========================================================================== */

/* 1. Rich Checklist Creator (Attachment Sheet) */
.rich-checklist-creator {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 4px 0;
}

.rich-checklist-creator-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 2px;
}

.rich-checklist-creator-header h3 {
  margin: 0;
  font-size: var(--font-size-body-large);
  font-weight: var(--font-weight-bold);
  color: var(--text-primary);
}

.checklist-creator-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: var(--radius-control);
  background: color-mix(in oklab, var(--accent-primary) 15%, transparent);
  color: var(--accent-primary);
  flex-shrink: 0;
}

.checklist-creator-error-banner {
  background: var(--color-palette-eb9b26aa7c52);
  border: 1px solid var(--color-palette-774f5df9b3a3);
  border-radius: var(--radius-control);
  padding: 8px 12px;
  color: var(--danger, var(--color-palette-c36d4cdccdc9));
  font-size: var(--font-size-small);
}

.checklist-creator-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.checklist-input-label {
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.checklist-category-selector {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

.checklist-cat-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 18px;
  border-radius: var(--radius-pill);
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
  border: 1px solid var(--border-default, var(--color-palette-b749cc259197));
  background: var(--surface-raised, var(--color-palette-0c501f182ba9));
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.18s ease;
}

.checklist-cat-btn:hover {
  background: var(--surface-hover, var(--color-palette-d635c939daff));
  color: var(--text-primary);
  border-color: var(--border-strong, var(--color-palette-d88cbf6be2ac));
}

.checklist-cat-btn.active {
  background: var(--accent-primary);
  color: var(--button-primary-text, var(--color-palette-f2074b6cef37));
  border-color: var(--accent-primary);
  box-shadow: none !important;
}

.checklist-text-input {
  background: var(--surface-raised, var(--color-palette-69142783e8a3));
  border: 1px solid var(--border-default, var(--color-palette-b749cc259197));
  border-radius: var(--radius-pill) !important;
  padding: 10px 18px !important;
  font-size: var(--font-size-body);
  color: var(--text-primary);
  width: 100%;
  box-sizing: border-box;
  outline: none;
  transition: border-color 0.15s ease;
}

.checklist-text-input:focus {
  border-color: var(--accent-primary);
  box-shadow: none !important;
}

.checklist-items-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.checklist-items-header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.checklist-voice-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--surface-raised, var(--color-palette-69142783e8a3));
  border: 1px solid var(--border-default, var(--color-palette-b749cc259197));
  border-radius: var(--radius-pill);
  padding: 4px 12px;
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  color: var(--text-secondary);
  cursor: not-allowed;
  opacity: 0.65;
  transition: all 0.15s ease;
}

.checklist-pro-badge {
  font-size: var(--font-size-micro);
  font-weight: var(--font-weight-extrabold);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: var(--accent-primary);
  color: var(--color-palette-f2074b6cef37);
  padding: 1px 5px;
  border-radius: var(--radius-small);
  line-height: 1.2;
}

.checklist-mic-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  min-width: 40px;
  border-radius: var(--radius-pill);
  background: var(--surface-raised, var(--color-palette-0c501f182ba9));
  border: 1px solid var(--border-default, var(--color-palette-b749cc259197));
  color: var(--text-secondary);
  cursor: not-allowed;
  opacity: 0.5;
  flex-shrink: 0;
  padding: 0;
  transition: all 0.15s ease;
}

.checklist-template-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 1px dashed var(--accent-primary);
  border-radius: var(--radius-pill);
  padding: 4px 12px;
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  color: var(--accent-primary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.checklist-template-btn:hover {
  background: color-mix(in oklab, var(--accent-primary) 12%, transparent);
}

.checklist-items-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 220px;
  overflow-y: auto;
  padding-right: 2px;
}

.checklist-items-list .checklist-item-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 10px;
  background: var(--surface-raised, var(--color-palette-8820ca375484));
  border: 1px solid var(--border-subtle, var(--color-palette-c34f5a2a4d80));
  border-radius: var(--radius-control);
}

.checklist-item-bullet-icon {
  color: var(--text-secondary);
  flex-shrink: 0;
}

.checklist-item-input {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--text-primary);
  font-size: var(--font-size-small);
  outline: none;
}

.checklist-item-section-tag {
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  padding: 2px 8px;
  border-radius: var(--radius-pill);
  background: color-mix(in oklab, var(--accent-primary) 15%, transparent);
  color: var(--accent-primary);
}

button.checklist-item-remove-btn,
.checklist-item-remove-btn {
  background: transparent !important;
  border: none !important;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 4px;
  border-radius: var(--radius-control);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color 0.15s ease;
  box-shadow: none !important;
}

button.checklist-item-remove-btn:hover,
.checklist-item-remove-btn:hover {
  color: var(--danger, var(--color-palette-c36d4cdccdc9)) !important;
  background: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
}

.checklist-add-row {
  display: flex;
  gap: 10px;
  align-items: center;
}

.checklist-add-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 18px;
  border-radius: var(--radius-pill);
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
  background: var(--accent-primary);
  border: 1px solid var(--accent-primary);
  color: var(--color-palette-f2074b6cef37);
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.15s ease;
}

.checklist-add-btn:hover:not(:disabled) {
  filter: brightness(1.08);
}

.checklist-add-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.checklist-creator-actions {
  display: flex;
  justify-content: flex-end;
  gap: 14px;
  margin-top: 6px;
  padding-top: 4px;
  border-top: none;
}

.checklist-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 22px;
  border-radius: var(--radius-pill);
  font-size: var(--font-size-small);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: all 0.18s ease;
}

.checklist-action-btn.secondary {
  background: var(--surface-raised, var(--color-palette-3748776e48d5));
  border: 1px solid var(--border-default, var(--color-palette-eabbb4eda5b3));
  color: var(--text-secondary);
}

.checklist-action-btn.secondary:hover:not(:disabled) {
  color: var(--text-primary);
  background: var(--surface-hover, var(--color-palette-b749cc259197));
}

.checklist-action-btn.primary {
  background: var(--accent-primary);
  border: 1px solid var(--accent-primary);
  color: var(--button-primary-text, var(--color-palette-f2074b6cef37));
  box-shadow: none !important;
}

.checklist-action-btn.primary:hover:not(:disabled) {
  filter: brightness(1.08);
}

.checklist-action-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* 2. Message Checklist Card (Chat Bubble) */
.message-checklist-card {
  background: color-mix(in oklab, var(--surface-card, var(--color-palette-ebe4f99c4351)) 90%, transparent);
  border: 1px solid var(--border-default, var(--color-palette-eabbb4eda5b3));
  border-radius: var(--radius-surface);
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 270px;
  max-width: 380px;
  box-shadow: 0 4px 14px var(--color-palette-8f59e80b6a29);
  color: var(--text-primary);
  box-sizing: border-box;
}

.message-checklist-card--unavailable {
  opacity: 0.65;
  align-items: center;
  flex-direction: row;
  gap: 10px;
}

.checklist-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.checklist-card-header-main {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
}

.checklist-card-icon-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  min-width: 34px;
  border-radius: var(--radius-control);
  background: color-mix(in oklab, var(--accent-primary) 18%, transparent);
  color: var(--accent-primary);
  flex-shrink: 0;
}

.checklist-card-title-wrap {
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
}

.checklist-card-category-tag {
  font-size: var(--font-size-micro);
  font-weight: var(--font-weight-bold);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--accent-primary);
  line-height: 1.2;
}

.checklist-card-title {
  font-size: var(--font-size-body);
  font-weight: var(--font-weight-bold);
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.checklist-card-open-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 12px;
  border-radius: var(--radius-pill);
  background: var(--surface-raised, var(--color-palette-c34f5a2a4d80));
  border: 1px solid var(--border-subtle, var(--color-palette-eabbb4eda5b3));
  color: var(--text-primary);
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.15s ease;
}

.checklist-card-open-btn:hover {
  background: var(--accent-primary);
  border-color: var(--accent-primary);
  color: var(--color-palette-f2074b6cef37);
}

.checklist-card-progress-wrap {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.checklist-card-progress-bar {
  height: 6px;
  background: var(--surface-raised, var(--color-palette-c34f5a2a4d80));
  border-radius: var(--radius-pill);
  overflow: hidden;
  width: 100%;
}

.checklist-card-progress-fill {
  height: 100%;
  background: var(--accent-primary);
  border-radius: var(--radius-pill);
  transition: width 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.checklist-card-progress-label {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  font-size: var(--font-size-caption);
  color: var(--text-secondary);
  font-weight: var(--font-weight-medium);
}

.checklist-card-progress-count {
  color: var(--text-secondary);
}

.checklist-card-progress-pct {
  color: var(--accent-primary);
  font-weight: var(--font-weight-bold);
}

.checklist-card-items-container {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 240px;
  overflow-y: auto;
  margin: 2px 0;
}

.checklist-card-section-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.checklist-card-section-title {
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-bold);
  color: var(--accent-primary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin: 4px 0 2px 8px;
  padding-left: 0;
}

.checklist-card-items-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.checklist-card-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 5px 8px;
  border-radius: var(--radius-control);
  cursor: pointer;
  transition: background 0.12s ease;
  min-height: 28px;
}

.checklist-card-item:hover {
  background: var(--surface-hover, var(--color-palette-3748776e48d5));
}

.checklist-card-item.is-completed .checklist-card-item-text {
  text-decoration: line-through;
  opacity: 0.55;
  color: var(--text-secondary);
}

/* Checkbox button: 20x20px circular Apple Reminders style */
.checklist-card-checkbox {
  width: 20px !important;
  height: 20px !important;
  min-width: 20px !important;
  min-height: 20px !important;
  max-width: 20px !important;
  max-height: 20px !important;
  border-radius: var(--radius-circle) !important;
  border: 2px solid var(--border-default, var(--color-palette-f6a93a8e2ede)) !important;
  background: transparent !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 0 !important;
  cursor: pointer !important;
  flex-shrink: 0 !important;
  transition: all 0.15s ease !important;
  color: var(--color-palette-f2074b6cef37) !important;
  box-sizing: border-box !important;
}

.checklist-card-checkbox.checked {
  background: var(--accent-primary) !important;
  border-color: var(--accent-primary) !important;
  color: var(--color-palette-f2074b6cef37) !important;
}

.checklist-card-checkbox:hover {
  border-color: var(--accent-primary) !important;
}

.checklist-card-item-text {
  font-size: var(--font-size-small);
  line-height: 1.35;
  color: var(--text-primary);
  word-break: break-word;
}

.checklist-card-quick-add {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 26px;
  box-sizing: border-box;
  padding: 1px 4px 1px 6px;
  background: var(--surface-raised, var(--color-palette-69142783e8a3));
  border: 1px solid var(--border-subtle, var(--color-palette-c34f5a2a4d80));
  border-radius: var(--radius-pill);
  margin-top: 2px;
}

.checklist-quick-add-bullet {
  color: var(--text-secondary);
  flex-shrink: 0;
}

input.checklist-card-add-input,
.checklist-card-quick-add input,
.checklist-card-add-input {
  flex: 1 !important;
  background: transparent !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  min-height: unset !important;
  height: auto !important;
  padding: 0 4px !important;
  font-size: var(--font-size-caption) !important;
  color: var(--text-primary) !important;
  width: auto !important;
}

input.checklist-card-add-input:focus,
.checklist-card-quick-add input:focus,
.checklist-card-add-input:focus {
  background: transparent !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}

.checklist-card-add-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--accent-primary);
  border: none;
  border-radius: var(--radius-circle) !important;
  box-sizing: border-box;
  height: 20px !important;
  min-height: 20px !important;
  padding: 0;
  width: 20px !important;
  min-width: 20px !important;
  aspect-ratio: 1;
  line-height: 1;
  font-weight: var(--font-weight-semibold);
  color: var(--color-palette-f2074b6cef37);
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.15s ease;
}

.checklist-card-add-submit:hover:not(:disabled) {
  filter: brightness(1.1);
}

.checklist-card-add-submit:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* 3. Full Checklist Page View */
.checklist-page-frame {
  min-height: 100dvh;
  background: var(--bg-app, var(--color-palette-65d96365d0c7));
}

.checklist-page-surface {
  display: flex;
  flex-direction: column;
  gap: 18px;
  max-width: 860px;
  margin: 0 auto;
  padding: 24px 32px;
  width: 100%;
  box-sizing: border-box;
}

.checklist-page-surface--loading,
.checklist-page-surface--error {
  align-items: center;
  justify-content: center;
  min-height: 60vh;
  text-align: center;
}

@media (max-width: 680px) {
  .checklist-page-surface {
    padding: 16px 14px;
    gap: 14px;
  }
}

.checklist-page-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-subtle, var(--color-palette-c34f5a2a4d80));
  width: 100%;
}

.checklist-header-info {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
  min-width: 0;
}

.checklist-title-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

.checklist-title-group h1 {
  margin: 0;
  font-size: var(--font-size-heading);
  font-weight: var(--font-weight-bold);
  color: var(--text-primary);
  word-break: break-word;
}

.checklist-title-input {
  background: transparent;
  border: none;
  border-bottom: 2px solid var(--accent-primary);
  color: var(--text-primary);
  font-size: var(--font-size-heading);
  font-weight: var(--font-weight-bold);
  outline: none;
  padding: 2px 0;
  width: 100%;
  max-width: 400px;
}

.checklist-title-edit {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 4px;
  border-radius: var(--radius-control);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: color 0.15s ease;
}

.checklist-title-edit:hover {
  color: var(--text-primary);
}

.checklist-category-pills {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.checklist-cat-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 14px;
  border-radius: var(--radius-pill);
