/* ── Unstyled button fixes ──────────────────────────────────────────────── */
/* stovo-doc-open-btn: "Open" button on document attachments                */
.stovo-doc-open-btn {
  background: var(--background-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-control);
  color: var(--text-primary);
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  height: 30px;
  padding: 0 12px;
  transition: background-color 150ms ease-out;
  white-space: nowrap;
}
.stovo-doc-open-btn:hover {
  background: var(--background-tertiary);
}

/* storage-new-btn: "+ New" button in the Storage page header              */
.storage-new-btn {
  background: var(--background-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-control);
  color: var(--text-primary);
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-semibold);
  height: 30px;
  padding: 0 12px;
  transition: background-color 150ms ease-out;
  white-space: nowrap;
}
.storage-new-btn:hover {
  background: var(--background-tertiary);
}

/* rsvp-btn: Yes / No RSVP buttons on event cards                          */
.rsvp-btn {
  background: var(--background-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-pill);
  color: var(--text-secondary);
  font-size: var(--font-size-caption);
  font-weight: var(--font-weight-bold);
  height: 28px;
  padding: 0 12px;
  transition: background-color 150ms ease-out, color 150ms ease-out;
  white-space: nowrap;
}
.rsvp-btn:hover:not(.active) {
  background: var(--background-tertiary);
  color: var(--text-primary);
}
.rsvp-btn.active {
  background: var(--accent-soft);
  border-color: var(--accent-border-soft);
  color: var(--accent-primary-hover);
}

